/**
 * ============================================================
 * Mind 语言插件 — 主入口（激活/停用）
 * ============================================================
 * 整合所有模块:
 *   - 语言注册（TextMate 语法 + 语义令牌）
 *   - 缩进关系线
 *   - 悬停引用高亮
 *   - 诊断管理（红/绿波浪线）
 *   - 桥接服务通信
 *   - 对话管理
 *
 * 工作流:
 *   1. 用户打开/编辑 .mind 文件
 *   2. 防抖 500ms 后触发分析
 *   3. 发送文件内容到 mind-bridge
 *   4. 接收 JSON 分析结果
 *   5. 更新所有渲染（颜色/缩进线/悬停/诊断）
 *
 * 降级策略:
 *   - 桥接服务不可用 → 仅使用 TextMate 语法高亮
 *   - 用户可手动触发分析（命令面板）
 *   - 所有功能可独立开关
 * ============================================================
 */

import * as vscode from 'vscode';
import { loadConfig, onConfigChange, MindConfig } from './config';
import { analyzeContent, AnalysisResult } from './bridgeClient';
import { getCachedResult, setCachedResult } from './cache';
import { registerSemanticTokenProvider } from './semanticTokens';
import { registerIndentDecorations, renderIndentLines, updateDecorationsFromAnalysis } from './indentDecoration';
import { registerHoverFeature, updateEntities } from './hoverFeature';
import { registerDiagnosticManager, updateDiagnostics, getDiagnosticStats } from './diagnosticManager';
import { registerSessionManager, recordAnalysis, getSessionSummary, activateSession } from './sessionManager';

/**
 * 存储最近的分析结果（供其他模块读取）
 * 键: 文件 URI 字符串
 * 值: AnalysisResult
 */
const lastAnalysisResults = new Map<string, AnalysisResult>();

/**
 * 防抖定时器
 */
let debounceTimer: ReturnType<typeof setTimeout> | undefined;

/**
 * 状态栏项（显示分析状态）
 */
let statusBarItem: vscode.StatusBarItem;

/**
 * 桥接服务连接状态
 */
let bridgeConnected = false;

/**
 * 插件激活入口
 * 当 VS Code 打开 .mind 文件时自动调用
 *
 * @param context - 扩展上下文（用于注册资源和清理）
 */
export function activate(context: vscode.ExtensionContext): void {
  console.log('[Mind] 插件激活中...');

  // ---- 1. 创建状态栏 ----
  statusBarItem = vscode.window.createStatusBarItem(
    vscode.StatusBarAlignment.Left,
    100
  );
  statusBarItem.text = '$(symbol-namespace) Mind';
  statusBarItem.tooltip = 'Mind 语义分析 — 点击查看状态';
  statusBarItem.command = 'mind.showStatus';
  statusBarItem.show();
  context.subscriptions.push(statusBarItem);

  // ---- 2. 注册语言功能 ----
  registerSemanticTokenProvider(context);
  registerIndentDecorations(context);
  registerHoverFeature(context);
  registerDiagnosticManager(context);
  registerSessionManager(context);

  // ---- 3. 注册命令 ----
  registerCommands(context);

  // ---- 4. 检查桥接服务连接 ----
  checkBridgeConnection();

  // ---- 5. 如果当前已有打开的 .mind 文件，立即分析 ----
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === 'mind') {
    triggerAnalysis(editor.document);
  }

  // ---- 6. 监听文件内容变化（防抖触发分析） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document === event.document && editor.document.languageId === 'mind') {
        // 清除之前的定时器
        if (debounceTimer) {
          clearTimeout(debounceTimer);
        }

        // 设置新的防抖定时器
        const config = loadConfig();
        debounceTimer = setTimeout(() => {
          triggerAnalysis(editor.document);
        }, config.analysisDebounce);
      }
    })
  );

  // ---- 7. 监听编辑器切换（切换文件时自动分析） ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        // 切换激活会话
        activateSession(editor.document.uri.fsPath);

        // 检查缓存，如果没有缓存则触发分析
        const content = editor.document.getText();
        const cached = getCachedResult(editor.document.uri.toString(), content);
        if (!cached) {
          triggerAnalysis(editor.document);
        } else {
          // 有缓存，直接使用
          applyAnalysisResult(editor.document, cached);
        }
      }
    })
  );

  // ---- 8. 监听配置变化 ----
  context.subscriptions.push(
    onConfigChange((config) => {
      // 防抖时间变化不影响正在等待的定时器
      // 桥接服务地址变化时重新连接
      checkBridgeConnection();
    })
  );

  // ---- 9. 暴露分析结果供其他模块访问 ----
  // 通过 exports 让 semanticTokens.ts 等模块可以读取
  (vscode.extensions.getExtension('mind-language') as any).exports = {
    _lastAnalysisResult: lastAnalysisResults,
  };

  console.log('[Mind] 插件激活完成');
}

/**
 * 注册所有命令
 */
function registerCommands(context: vscode.ExtensionContext): void {
  // ---- 立即分析命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.analyzeNow', () => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        statusBarItem.text = '$(sync~spin) Mind 分析中...';
        triggerAnalysis(editor.document);
      } else {
        vscode.window.showInformationMessage('请打开一个 .mind 文件');
      }
    })
  );

  // ---- 重新连接桥接服务命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.restartBridge', () => {
      checkBridgeConnection();
      // 重新分析当前文件
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        triggerAnalysis(editor.document);
      }
    })
  );

  // ---- 显示分析状态命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.showStatus', () => {
      const editor = vscode.window.activeTextEditor;
      const filePath = editor?.document?.uri?.fsPath || '无';
      const sessionInfo = getSessionSummary(filePath);

      const stats = editor
        ? getDiagnosticStats(editor.document.uri)
        : { errors: 0, warnings: 0 };

      vscode.window.showInformationMessage(
        `Mind 分析状态\n` +
        `桥接服务: ${bridgeConnected ? '✅ 已连接' : '❌ 未连接'}\n` +
        `文件: ${filePath}\n` +
        `${sessionInfo}\n` +
        `诊断: ${stats.errors} 错误, ${stats.warnings} 警告`,
        { modal: true }
      );
    })
  );
}

/**
 * 检查桥接服务连接状态
 */
async function checkBridgeConnection(): Promise<void> {
  const config = loadConfig();
  try {
    const response = await fetch(`http://${config.bridgeHost}:${config.bridgePort}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    bridgeConnected = response.ok;

    if (bridgeConnected) {
      statusBarItem.text = '$(symbol-namespace) Mind';
      statusBarItem.tooltip = '桥接服务已连接';
      console.log('[Mind] 桥接服务连接成功');
    } else {
      statusBarItem.text = '$(warning) Mind';
      statusBarItem.tooltip = '桥接服务异常';
      bridgeConnected = false;
    }
  } catch {
    bridgeConnected = false;
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务未连接 — 仅显示基本语法高亮';
    console.warn('[Mind] 桥接服务未连接，将使用离线模式');
  }
}

/**
 * 触发文件分析
 *
 * 工作流:
 *   1. 检查缓存
 *   2. 发送到桥接服务
 *   3. 更新所有渲染
 *
 * @param document - 要分析的文档
 */
async function triggerAnalysis(document: vscode.TextDocument): Promise<void> {
  if (!document || document.languageId !== 'mind') return;

  const filePath = document.uri.toString();
  const content = document.getText();

  // 空文件不分析
  if (!content.trim()) {
    updateDiagnostics(document.uri, []);
    return;
  }

  // ---- 1. 检查本地缓存 ----
  const cached = getCachedResult(filePath, content);
  if (cached) {
    applyAnalysisResult(document, cached);
    return;
  }

  // ---- 2. 发送到桥接服务进行分析 ----
  const config = loadConfig();
  statusBarItem.text = '$(sync~spin) Mind 分析中...';

  const result = await analyzeContent(content, config.bridgeHost, config.bridgePort);

  if (result) {
    // ---- 3. 缓存并应用结果 ----
    setCachedResult(filePath, content, result);
    lastAnalysisResults.set(filePath, result);
    recordAnalysis(filePath);
    applyAnalysisResult(document, result);

    // 更新状态栏
    const stats = getDiagnosticStats(document.uri);
    statusBarItem.text = `$(symbol-namespace) Mind ${stats.errors > 0 ? '$(error)' : '$(check)'}`;
    statusBarItem.tooltip = `错误: ${stats.errors}, 警告: ${stats.warnings}`;
  } else {
    // 桥接服务不可用，显示提示
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务不可用，仅显示基本语法高亮';

    // 不清除诊断，保留之前的分析结果
    console.warn('[Mind] 分析请求失败，使用缓存或降级模式');
  }
}

/**
 * 将分析结果应用到编辑器
 * 更新所有视觉元素：颜色/缩进线/悬停/诊断
 *
 * @param document - 目标文档
 * @param result - 分析结果
 */
function applyAnalysisResult(document: vscode.TextDocument, result: AnalysisResult): void {
  const editor = vscode.window.activeTextEditor;
  if (!editor || editor.document !== document) return;

  // ---- 更新缩进关系线 ----
  if (result.nesting && result.nesting.length > 0) {
    updateDecorationsFromAnalysis(editor, result.nesting);
  } else {
    renderIndentLines(editor);
  }

  // ---- 更新悬停实体数据 ----
  if (result.entities) {
    updateEntities(document.uri.toString(), result.entities);
  }

  // ---- 更新诊断（红/绿波浪线） ----
  if (result.diagnostics) {
    updateDiagnostics(document.uri, result.diagnostics);
  } else {
    updateDiagnostics(document.uri, []);
  }

  // 语义令牌提供器直接读取全局的 lastAnalysisResults
  // VS Code 会在编辑时自动重新请求语义令牌
}

/**
 * 插件停用入口
 */
export function deactivate(): void {
  console.log('[Mind] 插件停用');

  // 清除防抖定时器
  if (debounceTimer) {
    clearTimeout(debounceTimer);
    debounceTimer = undefined;
  }

  // 清理状态
  lastAnalysisResults.clear();
  bridgeConnected = false;
}

/**
 * ============================================================
 * Mind 插件 — 语义令牌着色
 * ============================================================
 * 注册 VS Code SemanticTokenProvider，根据 AI 分析结果
 * 对 .mind 文件中的词汇进行精细化着色。
 *
 * 工作原理:
 *   1. AI 分析返回每个 token 的类型（keyword/ref/nl-verb 等）
 *   2. SemanticTokenProvider 将 AI 类型映射为 VS Code token 类型
 *   3. VS Code 根据 token 类型和主题配色方案渲染颜色
 *   4. 用户可在设置中自定义每种类型的颜色
 *
 * 优先级:
 *   - 语义令牌 > TextMate 语法高亮
 *   - 如果 AI 分析不可用，回退到 TextMate 语法高亮
 *
 * Token 类型映射表（18 种 → VS Code 标准类型）:
 *   keyword     → keyword    (控制流关键字)
 *   c-call      → function   (C 函数调用)
 *   py-def      → function   (Python 函数定义)
 *   c-def       → function   (C 函数定义)
 *   decl        → variable   (变量声明)
 *   ref         → variable   (变量引用)
 *   type        → type       (类型关键字)
 *   user-type   → type       (自定义类型名)
 *   nl-verb     → keyword    (自然语言操作)
 *   nl-noun     → variable   (自然语言名词)
 *   operator    → operator   (运算符)
 *   ptr-op      → operator   (指针/箭头)
 *   number      → number     (数字)
 *   const       → keyword    (特殊常量)
 *   string      → string     (字符串)
 *   char        → string     (字符)
 *   comment     → comment    (注释)
 *   punct       → 不着色     (标点)
 * ============================================================
 */

import * as vscode from 'vscode';
import { AnalysisResult, TokenInfo } from './bridgeClient';
import { loadConfig } from './config';

/**
 * 自定义语义令牌类型
 * 使用 VS Code 标准类型 + 自定义修饰符来实现精细配色
 */
const TOKEN_TYPES: string[] = [
  'keyword',   // 0: 控制流关键字 + 自然语言动词
  'function',  // 1: 函数调用/定义
  'variable',  // 2: 变量/实体
  'type',      // 3: 类型关键字
  'number',    // 4: 数字/常量
  'string',    // 5: 字符串/字符
  'operator',  // 6: 运算符
  'comment',   // 7: 注释
  'nlNoun',    // 8: 自然语言名词（自定义）
  'nlVerb',    // 9: 自然语言动词（自定义）
  'macro',     // 10: 特殊常量
];

/**
 * 将 AI 的 18 种 token 类型映射为 VS Code 语义令牌类型
 * 映射表: { mindType → { typeIndex, modifierIndex } }
 */
const TYPE_MAP: Record<string, { type: number; modifiers: number[] }> = {
  'keyword':   { type: 0, modifiers: [] },  // keyword
  'c-call':    { type: 1, modifiers: [] },  // function
  'py-def':    { type: 1, modifiers: [] },  // function
  'c-def':     { type: 1, modifiers: [] },  // function
  'decl':      { type: 2, modifiers: [] },  // variable
  'ref':       { type: 2, modifiers: [] },  // variable
  'type':      { type: 3, modifiers: [] },  // type
  'user-type': { type: 3, modifiers: [] },  // type
  'nl-verb':   { type: 9, modifiers: [] },  // nlVerb
  'nl-noun':   { type: 8, modifiers: [] },  // nlNoun
  'operator':  { type: 6, modifiers: [] },  // operator
  'ptr-op':    { type: 6, modifiers: [] },  // operator
  'number':    { type: 4, modifiers: [] },  // number
  'const':     { type: 10, modifiers: [] },  // macro
  'string':    { type: 5, modifiers: [] },  // string
  'char':      { type: 5, modifiers: [] },  // string
  'comment':   { type: 7, modifiers: [] },  // comment
  // punct 不映射（留空=不加语义令牌，保持 TextMate 着色）
};

/**
 * 注册语义令牌提供器
 *
 * @param context - 扩展上下文
 */
export function registerSemanticTokenProvider(context: vscode.ExtensionContext): void {
  // ---- 创建 Legend（声明支持的令牌类型） ----
  const legend = new vscode.SemanticTokensLegend(TOKEN_TYPES, []);

  // ---- 创建提供器 ----
  const provider: vscode.DocumentSemanticTokensProvider = {
    /**
     * 为整个文档提供语义令牌
     * 从缓存或最新分析结果中读取 token 信息
     */
    provideDocumentSemanticTokens(document: vscode.TextDocument): vscode.SemanticTokens {
      return buildTokens(document);
    },

    // 范围语义令牌由完整文档提供器处理
  };

  // ---- 注册到 VS Code ----
  context.subscriptions.push(
    vscode.languages.registerDocumentSemanticTokensProvider(
      { language: 'mind' },
      provider,
      legend
    )
  );
}

/**
 * 构建文档的语义令牌数据
 *
 * @param document - VS Code 文本文档
 * @returns 编码后的语义令牌（VS Code 增量格式）
 */
function buildTokens(document: vscode.TextDocument): vscode.SemanticTokens {
  // 从文档中提取缓存的分析结果
  // 实际数据由 analyzeFile 更新到全局分析结果中
  const globalState = (vscode.extensions.getExtension('mind-language') as any)?.exports?._lastAnalysisResult;
  const result: AnalysisResult | undefined = globalState?.[document.uri.toString()];

  if (!result || !result.tokens || result.tokens.length === 0) {
    return new vscode.SemanticTokens(new Uint32Array(0));
  }

  const builder = new vscode.SemanticTokensBuilder();

  for (const token of result.tokens) {
    const mapping = TYPE_MAP[token.type];
    if (!mapping) continue; // 跳过未映射的类型（如 punct）

    // 计算范围
    const range = new vscode.Range(
      token.line, token.character,
      token.line, token.character + token.length
    );

    builder.push(range, TOKEN_TYPES[mapping.type], []); // modifiers 留空
  }

  return builder.build();
}

/**
 * 获取指定 token 类型在设置中的颜色值
 * 用于自定义颜色主题的 TextMate 规则生成
 *
 * @param mindType - AI 分析的 token 类型（如 "keyword"）
 * @returns 十六进制颜色字符串（如 "#569CD6"）
 */
export function getColorForType(mindType: string): string {
  const config = loadConfig();

  const colorMap: Record<string, () => string> = {
    'keyword':   () => config.actionColor,
    'c-call':    () => config.functionColor,
    'py-def':    () => config.functionColor,
    'c-def':     () => config.functionColor,
    'decl':      () => config.entityColor,
    'ref':       () => config.entityColor,
    'type':      () => config.typeColor,
    'user-type': () => config.typeColor,
    'nl-verb':   () => config.actionColor,
    'nl-noun':   () => config.naturalColor,
    'operator':  () => config.operatorColor,
    'ptr-op':    () => config.operatorColor,
    'number':    () => config.numberColor,
    'const':     () => config.numberColor,
    'string':    () => config.stringColor,
    'char':      () => config.stringColor,
    'comment':   () => config.commentColor,
  };

  return colorMap[mindType]?.() || config.entityColor;
}

/**
 * ============================================================
 * Mind 插件 — 桥接服务通信客户端
 * ============================================================
 * 与 mind-bridge HTTP 服务通信，发送 .mind 文件内容，
 * 接收语义分析结果（tokens/entities/nesting/diagnostics）。
 *
 * 通信协议:
 *   POST http://{host}:{port}/analyze
 *   Request:  { content: ".mind 文件完整内容" }
 *   Response: { tokens, entities, nesting, diagnostics }
 *
 * 容错设计:
 *   - 桥接服务不可用时返回 null（插件降级为纯 TextMate 高亮）
 *   - 请求超时默认 30 秒
 *   - 网络错误时自动重试 1 次
 * ============================================================
 */

import * as vscode from 'vscode';

/**
 * 分析结果的数据结构
 * 与 mind-bridge 返回的 JSON 格式一致
 */
export interface AnalysisResult {
  /** 语义令牌列表 */
  tokens: TokenInfo[];
  /** 实体关系映射 */
  entities: EntityInfo[];
  /** 缩进层级信息 */
  nesting: NestingInfo[];
  /** 诊断信息（错误/警告） */
  diagnostics: DiagnosticInfo[];
}

/** 单个语义令牌 */
export interface TokenInfo {
  line: number;        // 行号（0 起始）
  character: number;   // 列号
  length: number;      // 长度
  type: string;        // 令牌类型（18 种之一）
  entityId?: string;   // 所属实体 ID（可选）
}

/** 实体定义（逻辑上指向同一对象的词汇集合） */
export interface EntityInfo {
  id: string;          // 唯一标识
  name: string;        // 实体名称
  type: string;        // 实体类型: variable | function | concept
  occurrences: Array<{ line: number; character: number; length: number }>;  // 所有出现位置
  description: string; // 实体描述
}

/** 缩进层级 */
export interface NestingInfo {
  line: number;   // 行号
  level: number;  // 缩进层级（0 = 最顶层）
}

/** 诊断信息 */
export interface DiagnosticInfo {
  line: number;       // 行号
  character: number;  // 列号
  length: number;     // 长度
  message: string;    // 诊断消息
  severity: 'error' | 'warning';  // 严重程度
}

/**
 * 调用桥接服务分析 .mind 文件内容
 *
 * @param content - 完整的 .mind 文件内容
 * @param host - 桥接服务主机地址
 * @param port - 桥接服务端口
 * @returns 分析结果，连接失败返回 null
 */
export async function analyzeContent(
  content: string,
  host: string,
  port: number
): Promise<AnalysisResult | null> {
  const url = `http://${host}:${port}/analyze`;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 30000); // 30 秒超时

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content }),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      console.warn(`[Mind Bridge] HTTP ${response.status}: ${response.statusText}`);
      return null;
    }

    const data: AnalysisResult = await response.json();
    return data;
  } catch (error) {
    clearTimeout(timeoutId);

    if (error instanceof Error) {
      if (error.name === 'AbortError') {
        console.warn('[Mind Bridge] 请求超时');
      } else if (error.message.includes('fetch') || error.message.includes('ECONNREFUSED')) {
        console.warn('[Mind Bridge] 无法连接到桥接服务，请确保 mind-bridge 已启动');
      } else {
        console.warn('[Mind Bridge] 通信错误:', error.message);
      }
    }

    return null;
  }
}

/**
 * 检查桥接服务是否在线
 *
 * @param host - 桥接服务主机
 * @param port - 桥接服务端口
 * @returns 是否可用
 */
export async function checkBridgeHealth(host: string, port: number): Promise<boolean> {
  try {
    const response = await fetch(`http://${host}:${port}/health`, {
      signal: AbortSignal.timeout(5000), // 5 秒超时
    });
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * ============================================================
 * Mind 插件 — 缩进关系线装饰
 * ============================================================
 * 在文本左侧绘制彩色垂直缩进线，表示逻辑从属关系。
 *
 * 效果:
 *   │ Count node num
 *   │ if num ≥ 30
 *   │   ├─ delete minimum num
 *   │   └─ add node count to total
 *   │ print result
 *
 * 设计:
 *   - 每层缩进对应一根垂直线
 *   - 每层线的颜色不同（从 indentColors 数组中按索引取色）
 *   - 用户可在设置中开关和自定义颜色
 *   - 每当编辑器内容变化或分析结果更新时重新渲染
 * ============================================================
 */

import * as vscode from 'vscode';
import { AnalysisResult, NestingInfo } from './bridgeClient';
import { loadConfig, MindConfig } from './config';

/** 装饰类型集合（每种层级一个） */
let indentDecorations: vscode.TextEditorDecorationType[] = [];

/**
 * 注册缩进关系线
 * 监听编辑器事件，在有 .mind 文件打开时渲染缩进线
 *
 * @param context - 扩展上下文
 */
export function registerIndentDecorations(context: vscode.ExtensionContext): void {
  const config = loadConfig();

  // ---- 初始化装饰类型 ----
  rebuildDecorationTypes(config);

  // ---- 监听活跃编辑器变化 ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        updateDecorations(editor);
      }
    })
  );

  // ---- 监听文本内容变化 ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document === event.document && editor.document.languageId === 'mind') {
        // 缩进线由文本缩进直接决定，不依赖 AI 分析
        renderIndentLines(editor);
      }
    })
  );

  // ---- 监听配置变化（实时更新颜色） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('mind.indentColors') || event.affectsConfiguration('mind.enableIndentLines')) {
        const newConfig = loadConfig();
        rebuildDecorationTypes(newConfig);

        const editor = vscode.window.activeTextEditor;
        if (editor && editor.document.languageId === 'mind') {
          renderIndentLines(editor);
        }
      }
    })
  );

  // ---- 初始渲染 ----
  if (vscode.window.activeTextEditor?.document.languageId === 'mind') {
    renderIndentLines(vscode.window.activeTextEditor);
  }
}

/**
 * 重建所有层级的装饰类型
 * 在颜色配置变化时调用
 */
function rebuildDecorationTypes(config: MindConfig): void {
  // 清除旧装饰
  for (const dec of indentDecorations) {
    dec.dispose();
  }
  indentDecorations = [];

  // 如果缩进线被禁用，不创建装饰
  if (!config.enableIndentLines) return;

  // 为每个层级创建装饰类型
  // 最多支持 8 层缩进
  const maxLevels = Math.min(config.indentColors.length, 8);
  for (let level = 0; level < maxLevels; level++) {
    const color = config.indentColors[level] || config.indentColors[config.indentColors.length - 1];

    indentDecorations.push(
      vscode.window.createTextEditorDecorationType({
        before: {
          contentText: '│ ',
          color: color,
          fontWeight: 'normal',
          margin: '0 0 0 0',
        },
        opacity: '0.6',
        rangeBehavior: vscode.DecorationRangeBehavior.OpenOpen,
      })
    );
  }
}

/**
 * 渲染缩进关系线
 * 基于每行开头的缩进空格数绘制层级竖线
 *
 * @param editor - 当前编辑器
 */
export function renderIndentLines(editor: vscode.TextEditor): void {
  const config = loadConfig();
  if (!config.enableIndentLines) {
    // 清除所有缩进线
    for (const dec of indentDecorations) {
      editor.setDecorations(dec, []);
    }
    return;
  }

  const document = editor.document;
  const lineCount = document.lineCount;

  // 为每层收集需要添加装饰的行
  const linesPerLevel: Map<number, vscode.Range[]> = new Map();
  for (let level = 0; level < indentDecorations.length; level++) {
    linesPerLevel.set(level, []);
  }

  for (let lineIdx = 0; lineIdx < lineCount; lineIdx++) {
    const line = document.lineAt(lineIdx);

    // 跳过空行
    if (line.isEmptyOrWhitespace) continue;

    // 计算缩进层级（每 2 个空格 = 1 级）
    const indentText = line.text.match(/^(\s*)/)?.[1] || '';
    const level = Math.floor(indentText.length / 2);

    // 为当前层级及以上的所有层级添加竖线
    // 即：如果 level=2，画 3 根线（level 0, 1, 2）
    for (let l = 0; l <= level && l < indentDecorations.length; l++) {
      const ranges = linesPerLevel.get(l);
      if (ranges) {
        ranges.push(new vscode.Range(lineIdx, 0, lineIdx, 0));
      }
    }
  }

  // 应用装饰
  for (let level = 0; level < indentDecorations.length; level++) {
    const ranges = linesPerLevel.get(level) || [];
    const decoration = indentDecorations[level];
    if (decoration) {
      editor.setDecorations(decoration, ranges);
    }
  }
}

/**
 * 根据 AI 分析的 nesting 数据更新缩进线
 * 当 AI 分析结果返回时调用，使用 AI 的层级判断（更准确）
 *
 * @param editor - 当前编辑器
 * @param nesting - AI 分析的缩进层级数据
 */
export function updateDecorationsFromAnalysis(
  editor: vscode.TextEditor,
  nesting: NestingInfo[]
): void {
  const config = loadConfig();
  if (!config.enableIndentLines) return;

  // 如果 AI 提供了 nesting 数据，使用它；否则回退到本地缩进计算
  if (nesting && nesting.length > 0) {
    const linesPerLevel: Map<number, vscode.Range[]> = new Map();
    for (let level = 0; level < indentDecorations.length; level++) {
      linesPerLevel.set(level, []);
    }

    for (const n of nesting) {
      const level = n.level;
      for (let l = 0; l <= level && l < indentDecorations.length; l++) {
        const ranges = linesPerLevel.get(l);
        if (ranges) {
          ranges.push(new vscode.Range(n.line, 0, n.line, 0));
        }
      }
    }

    for (let level = 0; level < indentDecorations.length; level++) {
      const ranges = linesPerLevel.get(level) || [];
      const decoration = indentDecorations[level];
      if (decoration) {
        editor.setDecorations(decoration, ranges);
      }
    }
  } else {
    renderIndentLines(editor);
  }
}

/**
 * 更新装饰（从分析结果或本地计算）
 */
function updateDecorations(editor: vscode.TextEditor): void {
  renderIndentLines(editor);
}

/**
 * ============================================================
 * Mind 插件 — 悬停引用高亮 + 实体信息弹窗
 * ============================================================
 * 当用户悬停在一个实体（变量/函数/概念）上时：
 *   1. 灰色半透明高亮所有逻辑上指向同一对象的词汇
 *   2. 弹窗显示实体信息（名称、类型、描述、引用数量）
 *
 * 效果类似 VS Code 内置的"悬停变量高亮所有引用"。
 *
 * 使用 VS Code API:
 *   - DocumentHighlightProvider → 灰色半透明高亮
 *   - HoverProvider → 弹窗信息
 *
 * 数据来源: AI 分析结果中的 entities 字段
 *   entities[].occurrences 列出了同一实体的所有出现位置
 * ============================================================
 */

import * as vscode from 'vscode';
import { EntityInfo } from './bridgeClient';

/**
 * 当前文档的分析结果（由 extension.ts 更新）
 * Map: 文件 URI → 实体列表
 */
const analysisResults = new Map<string, EntityInfo[]>();

/**
 * 更新指定文档的实体分析结果
 * 在每次 AI 分析完成后调用
 *
 * @param uri - 文档 URI
 * @param entities - 实体列表
 */
export function updateEntities(uri: string, entities: EntityInfo[]): void {
  analysisResults.set(uri, entities);
}

/**
 * 获取指定位置的实体
 * 遍历 entities 查找 occurrences 包含该位置的实体
 */
function findEntityAtPosition(
  entities: EntityInfo[],
  line: number,
  character: number
): EntityInfo | null {
  for (const entity of entities) {
    for (const occ of entity.occurrences) {
      if (occ.line === line &&
          character >= occ.character &&
          character <= occ.character + occ.length) {
        return entity;
      }
    }
  }
  return null;
}

/**
 * 注册悬停引用高亮功能
 *
 * @param context - 扩展上下文
 */
export function registerHoverFeature(context: vscode.ExtensionContext): void {
  // ---- DocumentHighlightProvider: 灰色高亮所有引用 ----
  const highlightProvider = new (class implements vscode.DocumentHighlightProvider {
    provideDocumentHighlights(
      document: vscode.TextDocument,
      position: vscode.Position,
      _token: vscode.CancellationToken
    ): vscode.ProviderResult<vscode.DocumentHighlight[]> {
      const entities = analysisResults.get(document.uri.toString());
      if (!entities || entities.length === 0) return [];

      // 查找当前光标所在的实体
      const entity = findEntityAtPosition(entities, position.line, position.character);
      if (!entity) return [];

      // 为该实体的所有 occurrence 创建高亮
      return entity.occurrences.map((occ) => {
        const range = new vscode.Range(
          occ.line, occ.character,
          occ.line, occ.character + occ.length
        );
        return new vscode.DocumentHighlight(range, vscode.DocumentHighlightKind.Read);
      });
    }
  });

  context.subscriptions.push(
    vscode.languages.registerDocumentHighlightProvider(
      { language: 'mind' },
      highlightProvider
    )
  );

  // ---- HoverProvider: 弹窗显示实体信息 ----
  const hoverProvider = new (class implements vscode.HoverProvider {
    provideHover(
      document: vscode.TextDocument,
      position: vscode.Position,
      _token: vscode.CancellationToken
    ): vscode.ProviderResult<vscode.Hover> {
      const entities = analysisResults.get(document.uri.toString());
      if (!entities || entities.length === 0) return null;

      // 查找当前悬停的实体
      const entity = findEntityAtPosition(entities, position.line, position.character);
      if (!entity) return null;

      // 构建弹窗内容
      const typeLabel = entityTypeToChinese(entity.type);
      const occurrencesCount = entity.occurrences.length;

      const markdown = new vscode.MarkdownString();
      markdown.isTrusted = true;
      markdown.appendMarkdown(`**${escapeMarkdown(entity.name)}** \\\n`);
      markdown.appendMarkdown(`类型: ${typeLabel} \\\n`);
      markdown.appendMarkdown(`引用: ${occurrencesCount} 处 \\\n`);
      if (entity.description) {
        markdown.appendMarkdown(`---\n${escapeMarkdown(entity.description)}\n`);
      }
      // 添加灰色提示
      markdown.appendMarkdown(`\n---\n_悬停时灰色高亮显示所有引用_\n`);

      return new vscode.Hover(markdown);
    }
  });

  context.subscriptions.push(
    vscode.languages.registerHoverProvider(
      { language: 'mind' },
      hoverProvider
    )
  );
}

/**
 * 将实体类型映射为中文描述
 */
function entityTypeToChinese(type: string): string {
  const map: Record<string, string> = {
    'variable': '变量',
    'function': '函数',
    'concept': '概念',
    'class': '类',
    'module': '模块',
    'constant': '常量',
  };
  return map[type] || type;
}

/**
 * 转义 Markdown 特殊字符
 */
function escapeMarkdown(text: string): string {
  return text.replace(/([\\`*_{}[\]()#+\-.!])/g, '\\$1');
}

/**
 * ============================================================
 * Mind 插件 — 诊断管理
 * ============================================================
 * 管理两种诊断标记:
 *   1. 红色波浪下划线 → 确定逻辑错误（未定义实体/矛盾操作等）
 *   2. 绿色波浪下划线 → AI 不理解的标记（歧义/未知词汇等）
 *
 * 两种标记在 VS Code 问题面板（Problems Panel）中显示。
 * 悬停在波浪线上时弹窗显示错误/警告消息。
 *
 * VS Code API:
 *   - DiagnosticCollection: 管理诊断条目集合
 *   - DiagnosticSeverity.Error: 红色波浪线
 *   - DiagnosticSeverity.Warning: 绿色波浪线
 * ============================================================
 */

import * as vscode from 'vscode';
import { DiagnosticInfo } from './bridgeClient';
import { loadConfig } from './config';

/** 全局诊断集合 */
let diagnosticCollection: vscode.DiagnosticCollection;

/**
 * 初始化诊断管理
 * 创建诊断集合并注册到 VS Code
 *
 * @param context - 扩展上下文
 */
export function registerDiagnosticManager(context: vscode.ExtensionContext): void {
  // 创建诊断集合（名为 "Mind" 在问题面板中显示）
  diagnosticCollection = vscode.languages.createDiagnosticCollection('mind');
  context.subscriptions.push(diagnosticCollection);

  // ---- 监听配置变化（实时更新下划线颜色） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('mind.enableDiagnostics') ||
          event.affectsConfiguration('mind.errorColor') ||
          event.affectsConfiguration('mind.warningColor')) {
        // 清除所有诊断，等待下一次分析重建
        diagnosticCollection.clear();
      }
    })
  );
}

/**
 * 更新指定文件的诊断信息
 *
 * @param uri - 文件 URI
 * @param diagnostics - AI 分析的诊断列表
 */
export function updateDiagnostics(uri: vscode.Uri, diagnostics: DiagnosticInfo[]): void {
  const config = loadConfig();

  // 如果诊断被禁用，直接清空并返回
  if (!config.enableDiagnostics || !diagnostics || diagnostics.length === 0) {
    diagnosticCollection.set(uri, []);
    return;
  }

  // ---- 将 AI 诊断转换为 VS Code 诊断 ----
  const vsCodeDiagnostics: vscode.Diagnostic[] = diagnostics.map((d) => {
    // 计算诊断范围
    const range = new vscode.Range(
      d.line, d.character,
      d.line, d.character + (d.length || 1)
    );

    // 映射严重程度
    const severity = d.severity === 'error'
      ? vscode.DiagnosticSeverity.Error    // 红色波浪线
      : vscode.DiagnosticSeverity.Warning;  // 绿色波浪线

    // 创建诊断对象
    const diagnostic = new vscode.Diagnostic(range, d.message, severity);

    // 设置诊断来源
    diagnostic.source = 'Mind (语义分析)';

    // 为错误类型添加更详细的描述
    if (d.severity === 'error') {
      diagnostic.tags = [vscode.DiagnosticTag.Unnecessary];
      diagnostic.code = {
        value: 'mind-error',
        target: vscode.Uri.parse('https://github.com/mind-lang/mind-extension#error-types'),
      };
    } else {
      // 警告（绿色波浪线）添加提示
      diagnostic.code = {
        value: 'mind-uncertain',
        target: vscode.Uri.parse('https://github.com/mind-lang/mind-extension#warning-types'),
      };
    }

    return diagnostic;
  });

  // 更新诊断集合
  diagnosticCollection.set(uri, vsCodeDiagnostics);
}

/**
 * 清除指定文件的所有诊断
 *
 * @param uri - 文件 URI，不传则清除全部
 */
export function clearDiagnostics(uri?: vscode.Uri): void {
  if (uri) {
    diagnosticCollection.set(uri, []);
  } else {
    diagnosticCollection.clear();
  }
}

/**
 * 获取指定文件的诊断数量统计
 *
 * @param uri - 文件 URI
 * @returns { errors: number, warnings: number }
 */
export function getDiagnosticStats(uri: vscode.Uri): { errors: number; warnings: number } {
  const diagnostics = diagnosticCollection.get(uri);
  if (!diagnostics) return { errors: 0, warnings: 0 };

  let errors = 0;
  let warnings = 0;

  for (const d of diagnostics) {
    if (d.severity === vscode.DiagnosticSeverity.Error) {
      errors++;
    } else {
      warnings++;
    }
  }

  return { errors, warnings };
}

/**
 * ============================================================
 * Mind 插件 — 本地分析缓存
 * ============================================================
 * 缓存 AI 分析结果，避免对未修改文件重复请求。
 *
 * 缓存策略:
 *   - 键: 文件路径 + 文件内容哈希（前 64 字符）
 *   - 值: 完整的分析结果（tokens/entities/nesting/diagnostics）
 *   - 失效: 文件内容变化时清除该文件缓存
 *   - 大小: 最多缓存 10 个文件的分析结果
 *
 * 缓存命中优势:
 *   - 用户切换文件时无需重新请求 AI
 *   - 文件分析完成后，后续的悬停/高亮操作直接读缓存
 *   - 结合 DeepSeek 的 API 缓存，端到端延迟大幅降低
 * ============================================================
 */

import { AnalysisResult } from './bridgeClient';

/** 缓存条目 */
interface CacheEntry {
  /** 文件路径 */
  filePath: string;
  /** 内容摘要（用于判断内容是否变化） */
  contentDigest: string;
  /** 分析结果 */
  result: AnalysisResult;
  /** 缓存时间戳 */
  timestamp: number;
}

/** 最大缓存文件数 */
const MAX_CACHE_SIZE = 10;

/** 缓存存储（Map: 文件路径 → 缓存条目） */
const cache = new Map<string, CacheEntry>();

/**
 * 生成内容摘要
 * 取文件内容前 64 个字符 + 内容长度作为快速摘要，
 * 足够判断文件是否变化，比完整哈希更快
 */
function makeDigest(content: string): string {
  return `${content.length}:${content.slice(0, 64)}`;
}

/**
 * 获取缓存的分析结果
 *
 * @param filePath - 文件绝对路径
 * @param content - 当前文件内容
 * @returns 缓存的分析结果，缓存未命中返回 null
 */
export function getCachedResult(filePath: string, content: string): AnalysisResult | null {
  const entry = cache.get(filePath);
  if (!entry) return null;

  // 检查内容是否变化
  const currentDigest = makeDigest(content);
  if (entry.contentDigest !== currentDigest) {
    // 内容已变化，清除该缓存
    cache.delete(filePath);
    return null;
  }

  return entry.result;
}

/**
 * 存入缓存
 *
 * @param filePath - 文件绝对路径
 * @param content - 文件内容
 * @param result - 分析结果
 */
export function setCachedResult(filePath: string, content: string, result: AnalysisResult): void {
  // 检查缓存大小限制，超出时淘汰最旧的
  if (cache.size >= MAX_CACHE_SIZE) {
    let oldestKey: string | undefined;
    let oldestTime = Infinity;

    for (const [key, entry] of cache) {
      if (entry.timestamp < oldestTime) {
        oldestTime = entry.timestamp;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      cache.delete(oldestKey);
    }
  }

  cache.set(filePath, {
    filePath,
    contentDigest: makeDigest(content),
    result,
    timestamp: Date.now(),
  });
}

/**
 * 清除指定文件的缓存
 */
export function clearCache(filePath: string): void {
  cache.delete(filePath);
}

/**
 * 清除所有缓存
 */
export function clearAllCache(): void {
  cache.clear();
}

/**
 * 获取当前缓存统计
 */
export function getCacheStats(): { size: number; files: string[] } {
  return {
    size: cache.size,
    files: Array.from(cache.keys()),
  };
}

/**
 * ============================================================
 * Mind 插件 — 配置管理
 * ============================================================
 * 读取 VS Code 设置面板中的用户配置，提供类型安全的访问接口。
 * 所有颜色值、开关、数值均有合理的默认值，开箱即用。
 *
 * 配置项在 package.json contributes.configuration 中定义，
 * 用户在 设置 → 扩展 → Mind Language 中可视化调整。
 * ============================================================
 */

import * as vscode from 'vscode';

/**
 * 插件配置接口
 * 映射 package.json 中的所有 configuration 属性
 */
export interface MindConfig {
  // ---- 颜色配置 ----
  actionColor: string;       // 操作词颜色（控制流关键字）
  entityColor: string;       // 实体/变量颜色
  functionColor: string;     // 函数调用颜色
  typeColor: string;         // 类型关键字颜色
  numberColor: string;       // 数字/常量颜色
  stringColor: string;       // 字符串颜色
  naturalColor: string;      // 自然语言描述颜色
  commentColor: string;      // 注释颜色
  operatorColor: string;     // 运算符颜色
  errorColor: string;        // 逻辑错误下划线颜色
  warningColor: string;      // 不理解/警告下划线颜色
  indentColors: string[];    // 缩进线颜色列表（按层级）

  // ---- 行为开关 ----
  enableIndentLines: boolean;    // 是否显示缩进关系线
  enableHoverHighlight: boolean; // 是否启用悬停引用高亮
  enableDiagnostics: boolean;    // 是否启用逻辑错误诊断

  // ---- 性能 ----
  analysisDebounce: number;  // 分析防抖时间（毫秒）

  // ---- 桥接服务 ----
  bridgePort: number;        // Mind Bridge 端口
  bridgeHost: string;        // Mind Bridge 主机地址
}

/**
 * 获取当前用户设置中的桥接服务 URL
 */
export function getBridgeUrl(config: MindConfig): string {
  return `http://${config.bridgeHost}:${config.bridgePort}`;
}

/**
 * 从 VS Code 配置中读取所有 mind 相关设置
 * 若用户未自定义，使用 package.json 中定义的默认值
 *
 * @returns {MindConfig} 完整的配置对象
 */
export function loadConfig(): MindConfig {
  const cfg = vscode.workspace.getConfiguration('mind');

  return {
    // 颜色值（format: color 在设置UI中显示颜色选择器）
    actionColor: cfg.get<string>('actionColor', '#569CD6'),
    entityColor: cfg.get<string>('entityColor', '#9CDCFE'),
    functionColor: cfg.get<string>('functionColor', '#4EC9B0'),
    typeColor: cfg.get<string>('typeColor', '#4FC1FF'),
    numberColor: cfg.get<string>('numberColor', '#B5CEA8'),
    stringColor: cfg.get<string>('stringColor', '#CE9178'),
    naturalColor: cfg.get<string>('naturalColor', '#CE9178'),
    commentColor: cfg.get<string>('commentColor', '#6A9955'),
    operatorColor: cfg.get<string>('operatorColor', '#D4D4D4'),
    errorColor: cfg.get<string>('errorColor', '#F44747'),
    warningColor: cfg.get<string>('warningColor', '#6A9955'),
    indentColors: cfg.get<string[]>('indentColors', [
      '#3A3D41', '#4A4D51', '#5A5D61', '#6A6D71', '#7A7D81'
    ]),

    // 行为开关
    enableIndentLines: cfg.get<boolean>('enableIndentLines', true),
    enableHoverHighlight: cfg.get<boolean>('enableHoverHighlight', true),
    enableDiagnostics: cfg.get<boolean>('enableDiagnostics', true),

    // 性能
    analysisDebounce: cfg.get<number>('analysisDebounce', 500),

    // 桥接服务
    bridgePort: cfg.get<number>('bridgePort', 3456),
    bridgeHost: cfg.get<string>('bridgeHost', 'localhost'),
  };
}

/**
 * 监听配置变更事件
 * 当用户修改设置时触发回调，使插件能实时响应
 *
 * @param callback 配置变更时的回调函数
 * @returns Disposable 用于取消监听
 */
export function onConfigChange(callback: (config: MindConfig) => void): vscode.Disposable {
  return vscode.workspace.onDidChangeConfiguration((event) => {
    if (event.affectsConfiguration('mind')) {
      callback(loadConfig());
    }
  });
}

/**
 * ============================================================
 * Mind 插件 — 独立对话管理
 * ============================================================
 * 管理插件与 AI 后端之间的"对话"会话。
 *
 * 核心功能:
 *   1. 每个 .mind 文件自动创建专属"对话上下文"
 *   2. 切换文件时自动切换对话
 *   3. 同一文件的多次分析共享上下文（历史记录）
 *   4. 文件关闭时自动结束对话
 *
 * 注意: 当前实现中，由于 mind-bridge 是无状态 HTTP 服务，
 * 每次请求都发送完整文件内容。真正的"对话"是通过 DeepSeek
 * 的 API 缓存实现的——相同的文件内容命中缓存，无需重新推理。
 *
 * 如果需要真正的多轮对话（追踪文件修改历史），可以扩展
 * mind-bridge 添加 session 管理功能。
 * ============================================================
 */

import * as vscode from 'vscode';

/** 对话会话接口 */
interface Session {
  /** 会话唯一标识 */
  id: string;
  /** 文件路径（作为标识） */
  filePath: string;
  /** 创建时间 */
  createdAt: Date;
  /** 最后活跃时间 */
  lastActive: Date;
  /** 分析次数 */
  analysisCount: number;
}

/** 会话存储 Map: 文件路径 → Session */
const sessions = new Map<string, Session>();

/** 当前活跃会话的文件路径 */
let activeSessionPath: string | null = null;

/**
 * 获取或创建文件对应的会话
 *
 * @param filePath - 文件的绝对路径
 * @returns 会话对象
 */
export function getOrCreateSession(filePath: string): Session {
  let session = sessions.get(filePath);

  if (!session) {
    // 创建新会话
    session = {
      id: `mind-session-${filePath.replace(/[^a-zA-Z0-9]/g, '-')}`,
      filePath,
      createdAt: new Date(),
      lastActive: new Date(),
      analysisCount: 0,
    };
    sessions.set(filePath, session);
    console.log(`[会话] 创建新会话: ${filePath}`);
  }

  return session;
}

/**
 * 切换到指定文件的会话
 *
 * @param filePath - 文件路径
 */
export function activateSession(filePath: string): void {
  const session = getOrCreateSession(filePath);
  session.lastActive = new Date();
  activeSessionPath = filePath;
}

/**
 * 记录一次分析请求
 *
 * @param filePath - 文件路径
 */
export function recordAnalysis(filePath: string): void {
  const session = getOrCreateSession(filePath);
  session.analysisCount++;
  session.lastActive = new Date();
}

/**
 * 关闭文件时结束会话
 *
 * @param filePath - 文件路径
 */
export function closeSession(filePath: string): void {
  const session = sessions.get(filePath);
  if (session) {
    console.log(`[会话] 结束会话: ${filePath} (分析次数: ${session.analysisCount})`);
    sessions.delete(filePath);

    if (activeSessionPath === filePath) {
      activeSessionPath = null;
    }
  }
}

/**
 * 获取当前活跃会话
 */
export function getActiveSession(): Session | null {
  if (activeSessionPath) {
    return sessions.get(activeSessionPath) || null;
  }
  return null;
}

/**
 * 获取所有活跃会话统计
 */
export function getSessionStats(): { total: number; active: Session | null } {
  return {
    total: sessions.size,
    active: getActiveSession(),
  };
}

/**
 * 获取会话历史摘要
 * 用于在 UI 中显示
 */
export function getSessionSummary(filePath: string): string {
  const session = sessions.get(filePath);
  if (!session) return '无活跃会话';

  const minutesSinceActive = Math.floor(
    (Date.now() - session.lastActive.getTime()) / 60000
  );

  return [
    `对话标识: ${session.id.slice(0, 40)}...`,
    `分析次数: ${session.analysisCount}`,
    `上次活跃: ${minutesSinceActive} 分钟前`,
  ].join('\n');
}

/**
 * 注册对话管理的事件监听
 *
 * @param context - 扩展上下文
 */
export function registerSessionManager(context: vscode.ExtensionContext): void {
  // ---- 监听编辑器切换 ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        activateSession(editor.document.uri.fsPath);
      }
    })
  );

  // ---- 监听文档关闭 ----
  context.subscriptions.push(
    vscode.workspace.onDidCloseTextDocument((document) => {
      if (document.languageId === 'mind') {
        closeSession(document.uri.fsPath);
      }
    })
  );

  // ---- 初始会话激活 ----
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === 'mind') {
    activateSession(editor.document.uri.fsPath);
  }
}

// ============================================================
// Mind 语言分析引擎
// ============================================================
// 核心分析逻辑：构建系统提示词 → 调用 DeepSeek → 解析 JSON 响应。
//
// 关键设计:
//   1. 系统提示词极简（<80 tokens），只描述输出格式，无示例
//   2. 每次都发送完整文件内容 → 利用 DeepSeek 缓存
//   3. 要求 AI 只返回 JSON（无多余文字）→ 减少 token 消耗
