 * 使用 VS Code 标准类型 + 自定义修饰符来实现精细配色
 */
const TOKEN_TYPES: string[] = [
  'keyword',   // 0: 控制流关键字 + 自然语言动词
  'function',  // 1: 函数调用/定义
  'variable',  // 2: 变量/实体
  'type',      // 3: 类型关键字
  'number',    // 4: 数字/常量
  'string',    // 5: 字符串/字符
  'operator',  // 6: 运算符
  'comment',   // 7: 注释
  'nlNoun',    // 8: 自然语言名词（自定义）
  'nlVerb',    // 9: 自然语言动词（自定义）
  'macro',     // 10: 特殊常量
];

/**
 * 将 AI 的 18 种 token 类型映射为 VS Code 语义令牌类型
 * 映射表: { mindType → { typeIndex, modifierIndex } }
 */
const TYPE_MAP: Record<string, { type: number; modifiers: number[] }> = {
  'keyword':   { type: 0, modifiers: [] },  // keyword
  'c-call':    { type: 1, modifiers: [] },  // function
  'py-def':    { type: 1, modifiers: [] },  // function
  'c-def':     { type: 1, modifiers: [] },  // function
  'decl':      { type: 2, modifiers: [] },  // variable
  'ref':       { type: 2, modifiers: [] },  // variable
  'type':      { type: 3, modifiers: [] },  // type
  'user-type': { type: 3, modifiers: [] },  // type
  'nl-verb':   { type: 9, modifiers: [] },  // nlVerb
  'nl-noun':   { type: 8, modifiers: [] },  // nlNoun
  'operator':  { type: 6, modifiers: [] },  // operator
  'ptr-op':    { type: 6, modifiers: [] },  // operator
  'number':    { type: 4, modifiers: [] },  // number
  'const':     { type: 10, modifiers: [] },  // macro
  'string':    { type: 5, modifiers: [] },  // string
  'char':      { type: 5, modifiers: [] },  // string
  'comment':   { type: 7, modifiers: [] },  // comment
  // punct 不映射（留空=不加语义令牌，保持 TextMate 着色）
};

/**
 * 注册语义令牌提供器
 *
 * @param context - 扩展上下文
 */
export function registerSemanticTokenProvider(context: vscode.ExtensionContext): void {
  // ---- 创建 Legend（声明支持的令牌类型） ----
  const legend = new vscode.SemanticTokensLegend(TOKEN_TYPES, []);

  // ---- 创建提供器 ----
  const provider: vscode.DocumentSemanticTokensProvider = {
