 * 用于自定义颜色主题的 TextMate 规则生成
 *
 * @param mindType - AI 分析的 token 类型（如 "keyword"）
 * @returns 十六进制颜色字符串（如 "#569CD6"）
 */
export function getColorForType(mindType: string): string {
  const config = loadConfig();

  const colorMap: Record<string, () => string> = {
    'keyword':   () => config.actionColor,
    'c-call':    () => config.functionColor,
    'py-def':    () => config.functionColor,
    'c-def':     () => config.functionColor,
    'decl':      () => config.entityColor,
    'ref':       () => config.entityColor,
    'type':      () => config.typeColor,
    'user-type': () => config.typeColor,
    'nl-verb':   () => config.actionColor,
    'nl-noun':   () => config.naturalColor,
    'operator':  () => config.operatorColor,
    'ptr-op':    () => config.operatorColor,
    'number':    () => config.numberColor,
    'const':     () => config.numberColor,
    'string':    () => config.stringColor,
    'char':      () => config.stringColor,
    'comment':   () => config.commentColor,
  };

  return colorMap[mindType]?.() || config.entityColor;
}

