const analysisResults = new Map<string, EntityInfo[]>();

/**
 * 更新指定文档的实体分析结果
 * 在每次 AI 分析完成后调用
 *
 * @param uri - 文档 URI
 * @param entities - 实体列表
 */
export function updateEntities(uri: string, entities: EntityInfo[]): void {
  analysisResults.set(uri, entities);
}

