import { NestingInfo } from './bridgeClient';
import { loadConfig, MindConfig } from './config';

/**
 * 每个层级需要两种装饰类型:
 *   branchDecos[l]     — 有后续兄弟 → "├─ "
 *   lastChildDecos[l]  — 最后一个子节点 → "└─ "
