  console.log('║     Mind Bridge — 语义分析桥接服务已启动       ║');
  console.log(`║     监听端口: ${PORT}                            ║`);
  console.log('║     POST /analyze  — 分析 .mind 文件           ║');
  console.log('║     POST /generate — 生成 Python + C 代码       ║');
  console.log('║     GET  /health   — 健康检查                   ║');
  console.log('╚═══════════════════════════════════════════════╝');
  console.log(`[就绪] DeepSeek 模型: ${process.env.DEEPSEEK_MODEL || 'deepseek-v4-flash'}`);
});

// ============================================================
// DeepSeek API 客户端
// ============================================================
// 封装对 DeepSeek API 的调用，使用 OpenAI SDK 兼容接口。
//
// 特性:
//   - 自动重试（网络错误时最多重试 2 次）
//   - 超时控制（默认 30 秒）
//   - 响应校验（确保返回格式正确）
//   - 错误分类（认证/网络/限流等）
// ============================================================

import OpenAI from 'openai';

// ---- 初始化 DeepSeek 客户端 ----
// 使用 OpenAI SDK 连接 DeepSeek 的兼容 API 端点
const deepseek = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL || 'https://api.deepseek.com/v1',
  timeout: parseInt(process.env.REQUEST_TIMEOUT || '30000'),
  maxRetries: 2  // 网络错误时自动重试 2 次
});

// ---- 模型选择 ----
// 默认使用 flash 模型（快速+缓存友好）
// 可在 .env 中通过 DEEPSEEK_MODEL 覆盖
const DEFAULT_MODEL = process.env.DEEPSEEK_MODEL || 'deepseek-v4-flash';

/**
 * DeepSeek API 调用结果
 * @typedef {Object} DeepSeekResult
 * @property {string} content - AI 返回的文本内容
 * @property {Object} tokenUsage - Token 用量统计
 * @property {number} tokenUsage.prompt - 提示词 token 数
 * @property {number} tokenUsage.completion - 生成 token 数
 * @property {number} tokenUsage.total - 总 token 数
 * @property {number} tokenUsage.cached - 缓存命中的 prompt token 数
 */

/**
 * 调用 DeepSeek API 进行文本分析
 * @param {string} systemPrompt - 系统提示词（描述分析任务和格式）
 * @param {string} userContent - 用户输入（.mind 文件内容）
 * @returns {Promise<DeepSeekResult>} - AI 返回的文本 + token 用量
 * @throws {Error} - 包含分类错误信息
 */
export async function callDeepSeek(systemPrompt, userContent) {
  try {
    const response = await deepseek.chat.completions.create({
      model: DEFAULT_MODEL,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent }
      ],
      temperature: 0.1,           // 低温 → 输出更稳定、可预测
      max_tokens: 8192,           // 足够返回分析结果
      stream: false                // 非流式，直接获取完整 JSON
    });

    // 提取 AI 回复内容
    const message = response.choices?.[0]?.message;
    const result = message?.content;

    if (!result) {
      const hasReasoning = !!(message?.reasoning_content);
      const finishReason = response.choices?.[0]?.finish_reason;
      const detail = hasReasoning
        ? `模型推理消耗了所有 token 预算（finish_reason: ${finishReason}）`
        : `API 返回了空内容（finish_reason: ${finishReason}）`;
      throw new Error(`AI 返回了空响应: ${detail}`);
    }

    // 提取 token 用量（DeepSeek API 返回此数据）
    const usage = response.usage || {};
    const tokenUsage = {
      prompt: usage.prompt_tokens || 0,
      completion: usage.completion_tokens || 0,
      total: usage.total_tokens || 0,
      cached: usage.prompt_tokens_details?.cached_tokens || 0,
    };

    return { content: result, tokenUsage };

  } catch (error) {
    // ---- 错误分类 ----
    // DeepSeek/OpenAI SDK 错误已经包含了 HTTP 状态码
    if (error.status === 401) {
      const authError = new Error('API 密钥无效或未配置');
      authError.status = 401;
      throw authError;
    }

    if (error.status === 429) {
      const rateError = new Error('API 请求过于频繁，请稍后重试');
      rateError.status = 429;
      throw rateError;
    }

    if (error.status === 402) {
      const balanceError = new Error('DeepSeek 账户余额不足');
      balanceError.status = 402;
      throw balanceError;
    }

    if (error.code === 'ETIMEDOUT' || error.message.includes('timeout')) {
      const timeoutError = new Error('DeepSeek API 请求超时');
      timeoutError.code = 'ETIMEDOUT';
      throw timeoutError;
    }

    // 其他错误原样抛出
    throw error;
  }
}

// ============================================================
// Mind 语言分析引擎
// ============================================================
// 核心分析逻辑：构建系统提示词 → 调用 DeepSeek → 解析 JSON 响应。
//
// 关键设计:
//   1. 系统提示词极简（<80 tokens），只描述输出格式，无示例
//   2. 每次都发送完整文件内容 → 利用 DeepSeek 缓存
//   3. 要求 AI 只返回 JSON（无多余文字）→ 减少 token 消耗
//   4. 解析失败时返回空数据 + 诊断提示（不崩溃）
// ============================================================

import { callDeepSeek } from './deepseekClient.js';

// ============================================================
// 系统提示词
// ============================================================
// 设计原则:
//   - 固定不变 → 每次请求都命中 DeepSeek 缓存（零成本）
//   - 无示例 → 减少 token 数，让模型自己理解
//   - 明确指定 JSON 结构 → 确保解析成功
//   - 中文指令 → 与模型训练数据一致
//
// ⚠️ 警告：此提示词是性能关键路径。
//    修改后首次请求会 miss 缓存，后续命中。
// ============================================================
const SYSTEM_PROMPT = `分析 .mind 文件语义。

返回 JSON（只返回 JSON，不要其他文字）:
{
  "tokens": [{ line: 行号(0始), character: 列号, length: 长度, type: 类型 }],
  "entities": [{ id: "e1", name: "实体名", type: "variable|function|concept", occurrences: [{line,character,length}], description: "描述" }],
  "nesting": [{ line: 行号, level: 缩进层级 }],
  "diagnostics": [{ line, character, length, message, severity: "error|warning" }]
}

token 类型: keyword(控制流) c-call(C函数调用) py-def(Python函数定义) c-def(C函数定义) decl(变量声明) ref(变量引用) type(类型关键字) user-type(自定义类型) nl-verb(自然语言动词) nl-noun(自然语言名词) operator(运算符) ptr-op(指针/箭头) number(数字) const(特殊常量) string(字符串) char(字符) comment(注释) punct(标点)

entity 类型: variable(变量) function(函数) concept(抽象概念)
- 逻辑上指向同一对象的 token 归为同一个 entity
- 在 occurrences 中列出所有出现位置

nesting: 基于缩进空格数推断层级（0 = 最顶层）
diagnostics: error = 确定逻辑错误, warning = 不确定或歧义`;

/**
 * 从 AI 回复中提取 JSON
 * AI 有时会在 JSON 前后加 markdown 代码标记或其他文字
 */
function extractJSON(text) {
  if (!text || typeof text !== 'string') return null;

  // 清除 BOM 和首尾空白
  let cleaned = text.trim().replace(/^\uFEFF/, '');

  // 尝试直接解析
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // ---- 如果末尾字符不是 }，尝试补全截断的 JSON ----
    // 这是 DeepSeek 推理模型可能的问题：输出被 token 上限截断
    if (!cleaned.endsWith('}') && !cleaned.endsWith(']')) {
      // 尝试补全最外层大括号
      const openBraces = (cleaned.match(/\{/g) || []).length;
      const closeBraces = (cleaned.match(/\}/g) || []).length;
      if (openBraces > closeBraces) {
        cleaned += '}'.repeat(openBraces - closeBraces);
        try { return JSON.parse(cleaned); } catch { /* 继续尝试下一个策略 */ }
      }
    }

    // ---- 直接解析失败，使用 fallback 策略 ----
    // 常见的失败原因：AI 在 JSON 前后加了 markdown 代码块或额外文字

    // Fallback 1: 提取 ```json ... ``` 代码块
    const codeMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (codeMatch) {
      try { return JSON.parse(codeMatch[1].trim()); } catch { /* 继续 */ }
    }

    // Fallback 2: 用贪婪匹配提取最外层 {...} 或 [...]
    // 注意：必须用贪婪匹配，非贪婪会只匹配到第一个 } 导致截断
    // 例如 {"tokens":[{"line":0}]}extra → 贪婪正确匹配完整 JSON
    const outerMatch = text.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
    if (outerMatch) {
      try { return JSON.parse(outerMatch[0]); } catch { /* 继续 */ }
    }

    return null;
  }
}

/**
 * 验证分析结果的结构完整性
 */
function validateResult(result) {
  if (!result || typeof result !== 'object') return false;

  // tokens 应该是数组
  if (!Array.isArray(result.tokens)) result.tokens = [];

  // entities 应该是数组
  if (!Array.isArray(result.entities)) result.entities = [];

  // nesting 应该是数组
  if (!Array.isArray(result.nesting)) result.nesting = [];

  // diagnostics 应该是数组
  if (!Array.isArray(result.diagnostics)) result.diagnostics = [];

  // 确保每个 token 有必需字段
  result.tokens = result.tokens.filter(t =>
    typeof t.line === 'number' &&
    typeof t.character === 'number' &&
    typeof t.length === 'number' &&
    typeof t.type === 'string'
  );

  // 确保每个 entity 有必需字段
  result.entities = result.entities.filter(e =>
    typeof e.id === 'string' &&
    typeof e.name === 'string' &&
    Array.isArray(e.occurrences)
  );

  // 确保每个 nesting 有必需字段
  result.nesting = result.nesting.filter(n =>
    typeof n.line === 'number' &&
    typeof n.level === 'number'
  );

  // 确保每个 diagnostic 有必需字段
  result.diagnostics = result.diagnostics.filter(d =>
    typeof d.line === 'number' &&
    typeof d.character === 'number' &&
    typeof d.message === 'string' &&
    (d.severity === 'error' || d.severity === 'warning')
  );

  return true;
}

/**
 * 分析 .mind 文件内容
 * @param {string} content - 完整的 .mind 文件内容
 * @returns {Promise<{tokens: Array, entities: Array, nesting: Array, diagnostics: Array, tokenUsage?: Object}>}
 */
export async function analyzeMindContent(content) {
  // ---- 调用 DeepSeek API ----
  const { content: rawResponse, tokenUsage } = await callDeepSeek(SYSTEM_PROMPT, content);

  // ---- 解析 JSON ----
  const result = extractJSON(rawResponse);

  // ---- 附加 token 用量 ----
  if (result && tokenUsage) {
    result.tokenUsage = tokenUsage;
  }

  if (!result) {
    // 解析失败 → 返回空数据 + 诊断提示
    console.warn('[解析警告] AI 返回了无法解析的响应，已降级为纯高亮模式');
    console.warn('  原始响应(前300):', rawResponse.slice(0, 300));
    return {
      tokens: [],
      entities: [],
      nesting: computeFallbackNesting(content),
      diagnostics: [{
        line: 0,
        character: 0,
        length: 1,
        message: '语义分析暂时不可用，仅显示基本语法高亮',
        severity: 'warning'
      }]
    };
  }

  // ---- 验证结构 ----
  validateResult(result);

  // ---- 如果 diagnostics 为空但文件有内容，添加默认 nesting ----
  if (result.nesting.length === 0 && content.trim()) {
    result.nesting = computeFallbackNesting(content);
  }

  return result;
}

/**
 * 降级方案：当 AI 分析失败时，本地计算缩进层级
 * 基于每行开头的空格数推断缩进级别
 */
function computeFallbackNesting(content) {
  const lines = content.split('\n');
  const nesting = [];

  for (let line = 0; line < lines.length; line++) {
    const text = lines[line];
    // 计算开头的空格/制表符数
    const indentMatch = text.match(/^([ \t]*)/);
    const indentLength = indentMatch ? indentMatch[1].length : 0;

    // 忽略空行和纯注释行
    if (text.trim() === '' || text.trim().startsWith('#')) continue;

    // 估算层级（每 2 个空格 = 1 级）
    const level = Math.floor(indentLength / 2);

    nesting.push({ line, level });
  }

  return nesting;
}

// ============================================================
// Code Generator — .mind 注释驱动的 Python/C 代码生成器
// ============================================================
// 检测 .mind 文件中的 # @d 提问注释，
// 调用 DeepSeek 生成对应的 Python 和 C 实现代码，
// 返回结构化结果供插件写入文件并建立超链接。
//
// 工作流:
//   1. 解析 .mind 内容，提取所有 # @d 行
//   2. 构建生成提示词（极简，复用缓存优势）
//   3. 调用 DeepSeek API
//   4. 解析 JSON 响应，校验结构
//   5. 返回 { py: {code, links}, c: {code, links} }
// ============================================================

import { callDeepSeek } from './deepseekClient.js';

/**
 * 代码生成系统提示词
 * 极简设计：只描述输出格式，不包含示例
 */
const GENERATION_PROMPT = `你是一个代码生成助手。根据 .mind 文件中 # @d 开头的注释（提问/需求），生成 Python 3 和 C11 的完整实现代码。

返回 JSON（只返回 JSON）:
{
  "py": { "code": "完整Python文件", "links": [{"mindLine": 行号(0始), "fileLine": 函数起始行号, "name": "函数名"}] },
  "c": { "code": "完整C文件", "links": [{"mindLine": 行号, "fileLine": 函数起始行号, "name": "函数名"}] }
}

要求:
- Python 代码可直接运行，包含 import
- C 代码可编译，包含 #include 和头文件
- 代码中含详细中文注释解释每步逻辑
- links 将 # @d 所在行 → 对应的实现函数首行
- 如无 # @d 注释，返回空 code`;

/**
 * 检查 .mind 内容中是否包含 # @d 注释
 */
export function hasQueryComments(content) {
  return content.split('\n').some(line =>
    line.trim().startsWith('#') && line.includes('@d')
  );
}

/**
 * 提取所有 # @d 行及其行号
 */
function extractQueryLines(content) {
  const lines = content.split('\n');
  const queries = [];
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed.startsWith('#') && trimmed.includes('@d')) {
      queries.push({ line: i, text: trimmed });
    }
  }
  return queries;
}

/**
 * 从 AI 回复中提取并校验 JSON
 */
function extractJSON(text) {
  if (!text || typeof text !== 'string') return null;
  let cleaned = text.trim().replace(/^\uFEFF/, '');

  try { return JSON.parse(cleaned); } catch {
    // Fallback: 代码块
    const m = text.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (m) { try { return JSON.parse(m[1].trim()); } catch {} }
    // Fallback: 最外层大括号
    const b = text.match(/(\{[\s\S]*\})/);
    if (b) { try { return JSON.parse(b[0]); } catch {} }
    return null;
  }
}

/**
 * 校验生成结果的结构
 */
function validateResult(result) {
  if (!result || typeof result !== 'object') return null;

  // 确保 py 和 c 字段存在
  for (const lang of ['py', 'c']) {
    if (!result[lang] || typeof result[lang] !== 'object') {
      result[lang] = { code: '', links: [] };
    }
    if (typeof result[lang].code !== 'string') result[lang].code = '';
    if (!Array.isArray(result[lang].links)) result[lang].links = [];

    // 校验 links 中的每个条目
    result[lang].links = result[lang].links.filter(l =>
      typeof l.mindLine === 'number' &&
      typeof l.fileLine === 'number' &&
      typeof l.name === 'string'
    );
  }

  return result;
}

/**
 * 主入口：生成 Python + C 实现代码
 *
 * @param {string} mindContent - 完整 .mind 文件内容
 * @returns {Promise<{py: {code: string, links: Array}, c: {code: string, links: Array}}>}
 */
export async function generateCode(mindContent) {
  const queries = extractQueryLines(mindContent);

  if (queries.length === 0) {
    return {
      py: { code: '', links: [] },
      c: { code: '', links: [] }
    };
  }

  // ---- 调用 DeepSeek ----
  const { content: rawResponse } = await callDeepSeek(GENERATION_PROMPT, mindContent);

  const result = extractJSON(rawResponse);
  if (!result) {
    console.warn('[生成] AI 返回了无法解析的响应');
    return {
      py: { code: '# 代码生成失败，请检查桥接服务日志\n', links: [] },
      c: { code: '// 代码生成失败，请检查桥接服务日志\n', links: [] }
    };
  }

  return validateResult(result) || {
    py: { code: '', links: [] },
    c: { code: '', links: [] }
  };
}

/**
 * ============================================================
 * Mind 语言插件 — 主入口（激活/停用）
 * ============================================================
 * 整合所有模块:
 *   - 语言注册（TextMate 语法 + 语义令牌）
 *   - 缩进关系线
 *   - 悬停引用高亮
 *   - 诊断管理（红/绿波浪线）
 *   - 桥接服务通信
 *   - 对话管理
 *
 * 工作流:
 *   1. 用户打开/编辑 .mind 文件
 *   2. 防抖 500ms 后触发分析
 *   3. 发送文件内容到 mind-bridge
 *   4. 接收 JSON 分析结果
 *   5. 更新所有渲染（颜色/缩进线/悬停/诊断）
 *
 * 降级策略:
 *   - 桥接服务不可用 → 仅使用 TextMate 语法高亮
 *   - 用户可手动触发分析（命令面板）
 *   - 所有功能可独立开关
 * ============================================================
 */

import * as vscode from 'vscode';
import { loadConfig, onConfigChange } from './config';
import { analyzeContent, AnalysisResult } from './bridgeClient';
import { getCachedResult, setCachedResult } from './cache';
import { registerSemanticTokenProvider, updateSemanticResult, fireSemanticTokensChanged } from './semanticTokens';
import { registerIndentDecorations, renderIndentLines, updateDecorationsFromAnalysis } from './indentDecoration';
import { registerHoverFeature, updateEntities } from './hoverFeature';
import { registerDiagnosticManager, updateDiagnostics, getDiagnosticStats } from './diagnosticManager';
import { registerSessionManager, recordAnalysis, getSessionSummary } from './sessionManager';
import { generateCode as genCode, GenerationResult } from './bridgeClient';
import { ensureTripletFiles, writeGeneratedCode, getTriplet } from './fileTriplet';
import { registerDocLinks, updateGenerationData } from './docLinks';

/**
 * 定时器（行完成分析）
 * 只在按 Enter 后触发，行中编辑不触发任何分析
 */
let lineTimer: ReturnType<typeof setTimeout> | undefined;

/**
 * 进行中的分析请求对应的文档版本号
 * 用于丢弃过期请求的响应
 */
let pendingAnalysisVersion = 0;

/**
 * 状态栏项
 */
let statusBarItem: vscode.StatusBarItem;

/**
 * 桥接服务连接状态
 */
let bridgeConnected = false;

/**
 * 累计 token 消耗（本次会话）
 */
let totalTokensUsed = 0;
let totalCachedTokens = 0;

/** 行完成分析延迟：按 Enter 后等待 N ms 再触发分析 */
const LINE_COMPLETE_DELAY = 200;

/**
 * 插件激活入口
 * 当 VS Code 打开 .mind 文件时自动调用
 *
 * @param context - 扩展上下文（用于注册资源和清理）
 */
export function activate(context: vscode.ExtensionContext): void {
  console.log('[Mind] 插件激活中...');

  // ---- 1. 创建状态栏 ----
  statusBarItem = vscode.window.createStatusBarItem(
    vscode.StatusBarAlignment.Left,
    100
  );
  statusBarItem.text = '$(symbol-namespace) Mind';
  statusBarItem.tooltip = 'Mind 语义分析 — 点击查看状态';
  statusBarItem.command = 'mind.showStatus';
  statusBarItem.show();
  context.subscriptions.push(statusBarItem);

  // ---- 2. 注册语言功能 ----
  registerSemanticTokenProvider(context);
  registerIndentDecorations(context);
  registerHoverFeature(context);
  registerDiagnosticManager(context);
  registerSessionManager(context);
  registerDocLinks(context);

  // ---- 3. 注册命令 ----
  registerCommands(context);

  // ---- 4. 检查桥接服务连接 ----
  checkBridgeConnection();

  // ---- 5. 如果当前已有打开的 .mind 文件，立即分析 ----
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === 'mind') {
    ensureTripletFiles(editor.document.uri.fsPath);
    triggerAnalysis(editor.document);
  }

  // ---- 6. 逐行检测：只在按 Enter 后触发分析 ----
  // 策略（严格按你的要求）:
  //   - 只有写完一行（按 Enter）才触发分析
  //   - 行中编辑完全不触发，不浪费 token
  //   - 每次分析都处理整个文件（同步所有行的逻辑关系）
  //   - 悬停数据已缓存，鼠标悬停不额外请求
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (!editor || editor.document !== event.document || editor.document.languageId !== 'mind') return;

      // 检测是否按了 Enter（新行被插入）
      const hasNewLine = event.contentChanges.some(
        c => c.text.includes('\n') || c.text.includes('\r')
      );
      if (!hasNewLine) return; // 行中编辑 → 忽略

      // Enter 被按下 → 短延迟后分析整个文件
      if (lineTimer) clearTimeout(lineTimer);
      lineTimer = setTimeout(() => {
        triggerAnalysis(editor.document);
      }, LINE_COMPLETE_DELAY);
    })
  );

  // ---- 7. 监听编辑器切换（切换文件时自动分析） ----
  // 同时确保三文件体系完整
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        // 确保 .py 和 .c 文件存在
        ensureTripletFiles(editor.document.uri.fsPath);

        // 检查缓存，如果没有缓存则触发分析
        const content = editor.document.getText();
        const cached = getCachedResult(editor.document.uri.toString(), content);
        if (!cached) {
          triggerAnalysis(editor.document);
        } else {
          // 有缓存，直接使用
          applyAnalysisResult(editor.document, cached);
        }
      }
    })
  );

  // ---- 8. 监听配置变化 ----
  context.subscriptions.push(
    onConfigChange((config) => {
      // 防抖时间变化不影响正在等待的定时器
      // 桥接服务地址变化时重新连接
      checkBridgeConnection();
    })
  );

  console.log('[Mind] 插件激活完成');
}

/**
 * 注册所有命令
 */
function registerCommands(context: vscode.ExtensionContext): void {
  // ---- 立即分析命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.analyzeNow', () => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        statusBarItem.text = '$(sync~spin) Mind 分析中...';
        triggerAnalysis(editor.document);
      } else {
        vscode.window.showInformationMessage('请打开一个 .mind 文件');
      }
    })
  );

  // ---- 重新连接桥接服务命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.restartBridge', () => {
      checkBridgeConnection();
      // 重新分析当前文件
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document.languageId === 'mind') {
        triggerAnalysis(editor.document);
      }
    })
  );

  // ---- 显示分析状态命令 ----
  context.subscriptions.push(
    vscode.commands.registerCommand('mind.showStatus', () => {
      const editor = vscode.window.activeTextEditor;
      const filePath = editor?.document?.uri?.fsPath || '无';
      const sessionInfo = getSessionSummary(filePath);

      const stats = editor
        ? getDiagnosticStats(editor.document.uri)
        : { errors: 0, warnings: 0 };

      vscode.window.showInformationMessage(
        `Mind 分析状态\n` +
        `桥接服务: ${bridgeConnected ? '✅ 已连接' : '❌ 未连接'}\n` +
        `文件: ${filePath}\n` +
        `${sessionInfo}\n` +
        `诊断: ${stats.errors} 错误, ${stats.warnings} 警告`,
        { modal: true }
      );
    })
  );
}

/**
 * 检查桥接服务连接状态
 */
async function checkBridgeConnection(): Promise<void> {
  const config = loadConfig();
  try {
    const response = await fetch(`http://${config.bridgeHost}:${config.bridgePort}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    bridgeConnected = response.ok;

    if (bridgeConnected) {
      statusBarItem.text = '$(symbol-namespace) Mind';
      statusBarItem.tooltip = '桥接服务已连接';
      console.log('[Mind] 桥接服务连接成功');
    } else {
      statusBarItem.text = '$(warning) Mind';
      statusBarItem.tooltip = '桥接服务异常';
      bridgeConnected = false;
    }
  } catch {
    bridgeConnected = false;
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务未连接 — 仅显示基本语法高亮';
    console.warn('[Mind] 桥接服务未连接，将使用离线模式');
  }
}

/**
 * 触发文件分析
 *
 * 工作流:
 *   1. 检查缓存
 *   2. 发送到桥接服务
 *   3. 更新所有渲染
 *
 * @param document - 要分析的文档
 */
async function triggerAnalysis(document: vscode.TextDocument): Promise<void> {
  if (!document || document.languageId !== 'mind') return;

  const filePath = document.uri.toString();
  const content = document.getText();

  // 空文件不分析
  if (!content.trim()) {
    updateDiagnostics(document.uri, []);
    return;
  }

  // ---- 1. 检查本地缓存 ----
  const cached = getCachedResult(filePath, content);
  if (cached) {
    updateSemanticResult(filePath, cached);
    fireSemanticTokensChanged();
    applyAnalysisResult(document, cached);
    return;
  }

  // ---- 2. 记录当前请求的版本号（用于去重） ----
  pendingAnalysisVersion++;
  const thisVersion = pendingAnalysisVersion;
  const config = loadConfig();
  statusBarItem.text = '$(sync~spin) Mind 分析中...';

  const result = await analyzeContent(content, config.bridgeHost, config.bridgePort);

  // ---- 如果版本号变了，说明有更新请求已发出，丢弃本次结果 ----
  if (thisVersion !== pendingAnalysisVersion) {
    console.log('[Mind] 丢弃过期分析结果（版本', thisVersion, '→', pendingAnalysisVersion, '）');
    return;
  }

  if (result) {
    // ---- 3. 缓存并应用结果 ----
    setCachedResult(filePath, content, result);
    updateSemanticResult(filePath, result);
    recordAnalysis(filePath);
    applyAnalysisResult(document, result);
    fireSemanticTokensChanged();

    // ---- 4. 累计 token 并更新状态栏 ----
    if (result.tokenUsage) {
      totalTokensUsed += result.tokenUsage.total;
      totalCachedTokens += result.tokenUsage.cached;
      console.log(
        `[Token] ↑${result.tokenUsage.prompt} ↓${result.tokenUsage.completion}` +
        ` 缓存:${result.tokenUsage.cached} 累计:${totalTokensUsed}`
      );
    }

    // ---- 5. 检测 # @d 注释 → 触发代码生成 ----
    // 只在文本包含 # @d 时才调用 /generate（节省 token）
    if (content.includes('@d')) {
      triggerGeneration(document, config.bridgeHost, config.bridgePort);
    }

    const stats = getDiagnosticStats(document.uri);
    const tokenPart = totalTokensUsed > 0
      ? ` $(database)${totalTokensUsed}T`
      : '';
    statusBarItem.text = `$(symbol-namespace) Mind${tokenPart} ${stats.errors > 0 ? '$(error)' : '$(check)'}`;
    statusBarItem.tooltip = `错误: ${stats.errors}, 警告: ${stats.warnings} | 累计消耗: ${totalTokensUsed} tokens (缓存命中: ${totalCachedTokens})`;
  } else {
    // 桥接服务不可用，显示提示
    statusBarItem.text = '$(warning) Mind (离线)';
    statusBarItem.tooltip = '桥接服务不可用，仅显示基本语法高亮';

    // 不清除诊断，保留之前的分析结果
    console.warn('[Mind] 分析请求失败，使用缓存或降级模式');
  }
}

/**
 * 触发代码生成（# @d → Python + C）
 * 生成完成后写入文件并更新超链接
 */
async function triggerGeneration(
  document: vscode.TextDocument,
  host: string,
  port: number
): Promise<void> {
  const content = document.getText();
  const filePath = document.uri.fsPath;

  // 确保三文件体系完整
  await ensureTripletFiles(filePath);
  const triplet = getTriplet(filePath);

  // 调用桥接端 /generate
  const result = await genCode(content, host, port);
  if (!result || result.error) {
    console.warn('[生成] 代码生成失败:', result?.error);
    return;
  }

  // 写入生成的代码到文件
  if (result.py?.code) {
    await writeGeneratedCode(triplet.py, result.py);
  }
  if (result.c?.code) {
    await writeGeneratedCode(triplet.c, result.c);
  }

  // 更新超链接数据（供 DocumentLinkProvider 使用）
  updateGenerationData(document.uri.toString(), result);

  // 打开生成的文件（如果是首次创建）
  if (result.py?.code) {
    const pyDoc = await vscode.workspace.openTextDocument(triplet.py);
    // 不切换到该文件，只在后台打开
  }
  if (result.c?.code) {
    const cDoc = await vscode.workspace.openTextDocument(triplet.c);
  }

  console.log('[生成] 代码生成完成，已写入 .py 和 .c 文件');
}

/**
 * 将分析结果应用到编辑器
 * 更新所有视觉元素：颜色/缩进线/悬停/诊断
 *
 * @param document - 目标文档
 * @param result - 分析结果
 */
function applyAnalysisResult(document: vscode.TextDocument, result: AnalysisResult): void {
  const editor = vscode.window.activeTextEditor;
  if (!editor || editor.document !== document) return;

  // ---- 更新缩进关系线 ----
  if (result.nesting && result.nesting.length > 0) {
    updateDecorationsFromAnalysis(editor, result.nesting);
  } else {
    renderIndentLines(editor);
  }

  // ---- 更新悬停实体数据 ----
  if (result.entities) {
    updateEntities(document.uri.toString(), result.entities);
  }

  // ---- 更新诊断（红/绿波浪线） ----
  if (result.diagnostics) {
    updateDiagnostics(document.uri, result.diagnostics);
  } else {
    updateDiagnostics(document.uri, []);
  }

  // 语义令牌通过 updateSemanticResult() + fireSemanticTokensChanged() 更新
  // 已在 triggerAnalysis 中调用
}

/**
 * 插件停用入口
 */
export function deactivate(): void {
  console.log('[Mind] 插件停用');

  // 清除定时器
  if (lineTimer) { clearTimeout(lineTimer); lineTimer = undefined; }

  // 清理状态
  bridgeConnected = false;
}

/**
 * ============================================================
 * Mind 插件 — 配置管理
 * ============================================================
 * 读取 VS Code 设置面板中的用户配置，提供类型安全的访问接口。
 * 所有颜色值、开关、数值均有合理的默认值，开箱即用。
 *
 * 配置项在 package.json contributes.configuration 中定义，
 * 用户在 设置 → 扩展 → Mind Language 中可视化调整。
 * ============================================================
 */

import * as vscode from 'vscode';

/**
 * 插件配置接口
 * 映射 package.json 中的所有 configuration 属性
 */
export interface MindConfig {
  // ---- 颜色配置 ----
  actionColor: string;       // 操作词颜色（控制流关键字）
  entityColor: string;       // 实体/变量颜色
  functionColor: string;     // 函数调用颜色
  typeColor: string;         // 类型关键字颜色
  numberColor: string;       // 数字/常量颜色
  stringColor: string;       // 字符串颜色
  naturalColor: string;      // 自然语言描述颜色
  commentColor: string;      // 注释颜色
  operatorColor: string;     // 运算符颜色
  errorColor: string;        // 逻辑错误下划线颜色
  warningColor: string;      // 不理解/警告下划线颜色
  indentColors: string[];    // 缩进线颜色列表（按层级）

  // ---- 行为开关 ----
  enableIndentLines: boolean;    // 是否显示缩进关系线
  enableHoverHighlight: boolean; // 是否启用悬停引用高亮
  enableDiagnostics: boolean;    // 是否启用逻辑错误诊断

  // ---- 性能 ----
  analysisDebounce: number;  // 分析防抖时间（毫秒）

  // ---- 桥接服务 ----
  bridgePort: number;        // Mind Bridge 端口
  bridgeHost: string;        // Mind Bridge 主机地址
}

/**
 * 获取当前用户设置中的桥接服务 URL
 */
export function getBridgeUrl(config: MindConfig): string {
  return `http://${config.bridgeHost}:${config.bridgePort}`;
}

/**
 * 从 VS Code 配置中读取所有 mind 相关设置
 * 若用户未自定义，使用 package.json 中定义的默认值
 *
 * @returns {MindConfig} 完整的配置对象
 */
export function loadConfig(): MindConfig {
  const cfg = vscode.workspace.getConfiguration('mind');

  return {
    // 颜色值（format: color 在设置UI中显示颜色选择器）
    actionColor: cfg.get<string>('actionColor', '#569CD6'),
    entityColor: cfg.get<string>('entityColor', '#9CDCFE'),
    functionColor: cfg.get<string>('functionColor', '#4EC9B0'),
    typeColor: cfg.get<string>('typeColor', '#4FC1FF'),
    numberColor: cfg.get<string>('numberColor', '#B5CEA8'),
    stringColor: cfg.get<string>('stringColor', '#CE9178'),
    naturalColor: cfg.get<string>('naturalColor', '#CE9178'),
    commentColor: cfg.get<string>('commentColor', '#6A9955'),
    operatorColor: cfg.get<string>('operatorColor', '#D4D4D4'),
    errorColor: cfg.get<string>('errorColor', '#F44747'),
    warningColor: cfg.get<string>('warningColor', '#6A9955'),
    indentColors: cfg.get<string[]>('indentColors', [
      '#3A3D41', '#4A4D51', '#5A5D61', '#6A6D71', '#7A7D81'
    ]),

    // 行为开关
    enableIndentLines: cfg.get<boolean>('enableIndentLines', true),
    enableHoverHighlight: cfg.get<boolean>('enableHoverHighlight', true),
    enableDiagnostics: cfg.get<boolean>('enableDiagnostics', true),

    // 性能
    analysisDebounce: cfg.get<number>('analysisDebounce', 500),

    // 桥接服务
    bridgePort: cfg.get<number>('bridgePort', 3456),
    bridgeHost: cfg.get<string>('bridgeHost', 'localhost'),
  };
}

/**
 * 监听配置变更事件
 * 当用户修改设置时触发回调，使插件能实时响应
 *
 * @param callback 配置变更时的回调函数
 * @returns Disposable 用于取消监听
 */
export function onConfigChange(callback: (config: MindConfig) => void): vscode.Disposable {
  return vscode.workspace.onDidChangeConfiguration((event) => {
    // 只监听桥接地址和端口的变化（其他配置在具体模块中单独监听）
    if (event.affectsConfiguration('mind.bridgeHost') ||
        event.affectsConfiguration('mind.bridgePort')) {
      callback(loadConfig());
    }
  });
}

/**
 * ============================================================
 * Mind 插件 — 桥接服务通信客户端
 * ============================================================
 * 与 mind-bridge HTTP 服务通信，发送 .mind 文件内容，
 * 接收语义分析结果（tokens/entities/nesting/diagnostics）。
 *
 * 通信协议:
 *   POST http://{host}:{port}/analyze
 *   Request:  { content: ".mind 文件完整内容" }
 *   Response: { tokens, entities, nesting, diagnostics }
 *
 * 容错设计:
 *   - 桥接服务不可用时返回 null（插件降级为纯 TextMate 高亮）
 *   - 请求超时默认 30 秒
 *   - 网络错误时自动重试 1 次
 * ============================================================
 */

import * as vscode from 'vscode';

/**
 * 分析结果的数据结构
 * 与 mind-bridge 返回的 JSON 格式一致
 */
export interface AnalysisResult {
  /** 语义令牌列表 */
  tokens: TokenInfo[];
  /** 实体关系映射 */
  entities: EntityInfo[];
  /** 缩进层级信息 */
  nesting: NestingInfo[];
  /** 诊断信息（错误/警告） */
  diagnostics: DiagnosticInfo[];
  /** Token 用量统计（API 返回时才有） */
  tokenUsage?: TokenUsage;
}

/** 单个语义令牌 */
export interface TokenInfo {
  line: number;        // 行号（0 起始）
  character: number;   // 列号
  length: number;      // 长度
  type: string;        // 令牌类型（18 种之一）
  entityId?: string;   // 所属实体 ID（可选）
}

/** 实体定义（逻辑上指向同一对象的词汇集合） */
export interface EntityInfo {
  id: string;          // 唯一标识
  name: string;        // 实体名称
  type: string;        // 实体类型: variable | function | concept
  occurrences: Array<{ line: number; character: number; length: number }>;  // 所有出现位置
  description: string; // 实体描述
}

/** 缩进层级 */
export interface NestingInfo {
  line: number;   // 行号
  level: number;  // 缩进层级（0 = 最顶层）
}

/** 诊断信息 */
export interface DiagnosticInfo {
  line: number;       // 行号
  character: number;  // 列号
  length: number;     // 长度
  message: string;    // 诊断消息
  severity: 'error' | 'warning';  // 严重程度
}

/** Token 用量统计 */
export interface TokenUsage {
  prompt: number;      // 提示词 token 数
  completion: number;  // 生成 token 数
  total: number;       // 总 token 数
  cached: number;      // 缓存命中的 prompt token 数
}

/**
 * 调用桥接服务分析 .mind 文件内容
 *
 * @param content - 完整的 .mind 文件内容
 * @param host - 桥接服务主机地址
 * @param port - 桥接服务端口
 * @returns 分析结果，连接失败返回 null
 */
export async function analyzeContent(
  content: string,
  host: string,
  port: number
): Promise<AnalysisResult | null> {
  const url = `http://${host}:${port}/analyze`;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 30000); // 30 秒超时

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content }),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      console.warn(`[Mind Bridge] HTTP ${response.status}: ${response.statusText}`);
      return null;
    }

    const data: unknown = await response.json();

    // ---- 运行时类型校验（修复 Bug 5） ----
    if (!isValidAnalysisResult(data)) {
      console.warn('[Mind Bridge] 响应格式不正确，已忽略');
      return null;
    }

    return data;
  } catch (error) {
    clearTimeout(timeoutId);

    if (error instanceof Error) {
      if (error.name === 'AbortError') {
        console.warn('[Mind Bridge] 请求超时');
      } else if (error.message.includes('fetch') || error.message.includes('ECONNREFUSED')) {
        console.warn('[Mind Bridge] 无法连接到桥接服务，请确保 mind-bridge 已启动');
      } else {
        console.warn('[Mind Bridge] 通信错误:', error.message);
      }
    }

    return null;
  }
}

// ============================================================
// 代码生成接口
// ============================================================

/** 单个代码文件的生成结果 */
export interface FileCode {
  /** 完整的文件代码 */
  code: string;
  /** 超链接映射：.mind 注释行 → 实现函数位置 */
  links: Array<{
    mindLine: number;   // .mind 中 # @d 的行号（0起始）
    fileLine: number;   // .py/.c 中函数起始行号（0起始）
    name: string;       // 函数名
  }>;
}

/** 代码生成响应 */
export interface GenerationResult {
  py: FileCode;
  c: FileCode;
  /** 桥接端返回的备注 */
  note?: string;
  /** 错误信息 */
  error?: string;
}

/**
 * 调用桥接服务生成 Python + C 代码
 *
 * @param content - 完整的 .mind 文件内容
 * @param host - 桥接服务主机
 * @param port - 桥接服务端口
 * @returns 生成结果，失败返回 null
 */
export async function generateCode(
  content: string,
  host: string,
  port: number
): Promise<GenerationResult | null> {
  const url = `http://${host}:${port}/generate`;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000); // 60 秒超时

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content }),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);
    if (!response.ok) return null;

    const data: GenerationResult = await response.json();
    return data;
  } catch (error) {
    clearTimeout(timeoutId);
    console.warn('[Mind Generate] 代码生成请求失败:', error instanceof Error ? error.message : '');
    return null;
  }
}

/**
 * 运行时校验桥接响应是否符合 AnalysisResult 结构
 */
function isValidAnalysisResult(data: unknown): data is AnalysisResult {
  if (!data || typeof data !== 'object') return false;

  const obj = data as Record<string, unknown>;

  // 检查 tokens
  if (!Array.isArray(obj.tokens)) return false;
  for (const t of obj.tokens) {
    if (!t || typeof t !== 'object') return false;
    const tok = t as Record<string, unknown>;
    if (typeof tok.line !== 'number' || typeof tok.character !== 'number' ||
        typeof tok.length !== 'number' || typeof tok.type !== 'string') {
      return false;
    }
  }

  // entities 可选，如果有则校验
  if (obj.entities !== undefined) {
    if (!Array.isArray(obj.entities)) return false;
  }

  // nesting 可选
  if (obj.nesting !== undefined) {
    if (!Array.isArray(obj.nesting)) return false;
  }

  // diagnostics 可选
  if (obj.diagnostics !== undefined) {
    if (!Array.isArray(obj.diagnostics)) return false;
  }

  return true;
}

/**
 * 检查桥接服务是否在线
 *
 * @param host - 桥接服务主机
 * @param port - 桥接服务端口
 * @returns 是否可用
 */
export async function checkBridgeHealth(host: string, port: number): Promise<boolean> {
  try {
    const response = await fetch(`http://${host}:${port}/health`, {
      signal: AbortSignal.timeout(5000), // 5 秒超时
    });
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * ============================================================
 * Mind 插件 — 本地分析缓存
 * ============================================================
 * 缓存 AI 分析结果，避免对未修改文件重复请求。
 *
 * 缓存策略:
 *   - 键: 文件路径 + 文件内容哈希（前 64 字符）
 *   - 值: 完整的分析结果（tokens/entities/nesting/diagnostics）
 *   - 失效: 文件内容变化时清除该文件缓存
 *   - 大小: 最多缓存 10 个文件的分析结果
 *
 * 缓存命中优势:
 *   - 用户切换文件时无需重新请求 AI
 *   - 文件分析完成后，后续的悬停/高亮操作直接读缓存
 *   - 结合 DeepSeek 的 API 缓存，端到端延迟大幅降低
 * ============================================================
 */

import { AnalysisResult } from './bridgeClient';

/** 缓存条目 */
interface CacheEntry {
  /** 文件路径 */
  filePath: string;
  /** 内容摘要（用于判断内容是否变化） */
  contentDigest: string;
  /** 分析结果 */
  result: AnalysisResult;
  /** 缓存时间戳 */
  timestamp: number;
}

/** 最大缓存文件数 */
const MAX_CACHE_SIZE = 10;

/** 缓存存储（Map: 文件路径 → 缓存条目） */
const cache = new Map<string, CacheEntry>();

/**
 * 生成内容摘要
 * 取文件内容前 64 个字符 + 内容长度作为快速摘要，
 * 足够判断文件是否变化，比完整哈希更快
 */
function makeDigest(content: string): string {
  return `${content.length}:${content.slice(0, 64)}`;
}

/**
 * 获取缓存的分析结果
 *
 * @param filePath - 文件绝对路径
 * @param content - 当前文件内容
 * @returns 缓存的分析结果，缓存未命中返回 null
 */
export function getCachedResult(filePath: string, content: string): AnalysisResult | null {
  const entry = cache.get(filePath);
  if (!entry) return null;

  // 检查内容是否变化
  const currentDigest = makeDigest(content);
  if (entry.contentDigest !== currentDigest) {
    // 内容已变化，清除该缓存
    cache.delete(filePath);
    return null;
  }

  return entry.result;
}

/**
 * 存入缓存
 *
 * @param filePath - 文件绝对路径
 * @param content - 文件内容
 * @param result - 分析结果
 */
export function setCachedResult(filePath: string, content: string, result: AnalysisResult): void {
  // 检查缓存大小限制，超出时淘汰最旧的
  if (cache.size >= MAX_CACHE_SIZE) {
    let oldestKey: string | undefined;
    let oldestTime = Infinity;

    for (const [key, entry] of cache) {
      if (entry.timestamp < oldestTime) {
        oldestTime = entry.timestamp;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      cache.delete(oldestKey);
    }
  }

  cache.set(filePath, {
    filePath,
    contentDigest: makeDigest(content),
    result,
    timestamp: Date.now(),
  });
}

/**
 * 清除指定文件的缓存
 */
export function clearCache(filePath: string): void {
  cache.delete(filePath);
}

/**
 * 清除所有缓存
 */
export function clearAllCache(): void {
  cache.clear();
}

/**
 * 获取当前缓存统计
 */
export function getCacheStats(): { size: number; files: string[] } {
  return {
    size: cache.size,
    files: Array.from(cache.keys()),
  };
}

/**
 * ============================================================
 * Mind 插件 — 缩进关系线装饰
 * ============================================================
 * 在文本左侧绘制彩色垂直缩进线，表示逻辑从属关系。
 *
 * 效果:
 *   │ Count node num
 *   │ if num ≥ 30
 *   │   ├─ delete minimum num
 *   │   └─ add node count to total
 *   │ print result
 *
 * 实现:
 *   - 顶层级 (level 0): 使用 │  前缀
 *   - 子层级 (level > 0): 根据是否有后续兄弟节点决定 ├─ 或 └─
 *   - 每层颜色不同，可配置
 *   - 同时渲染连续竖线（延续线），显示从属结构
 * ============================================================
 */

import * as vscode from 'vscode';
import { loadConfig, MindConfig } from './config';

/**
 * 每个层级需要两种装饰类型:
 *   branchDecos[l]     — 有后续兄弟 → "├─ "
 *   lastChildDecos[l]  — 最后一个子节点 → "└─ "
 *   contDecos[l]       — 延续竖线（该层级之后还有行）→ "│ "
 */
let branchDecos: vscode.TextEditorDecorationType[] = [];
let lastChildDecos: vscode.TextEditorDecorationType[] = [];
let contDecos: vscode.TextEditorDecorationType[] = [];

/**
 * 注册缩进关系线
 */
export function registerIndentDecorations(context: vscode.ExtensionContext): void {
  rebuildDecorationTypes(loadConfig());

  // ---- 活跃编辑器切换 ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor?.document.languageId === 'mind') {
        renderIndentLines(editor);
      }
    })
  );

  // ---- 文本内容变化 ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeTextDocument((event) => {
      const editor = vscode.window.activeTextEditor;
      if (editor && editor.document === event.document && editor.document.languageId === 'mind') {
        renderIndentLines(editor);
      }
    })
  );

  // ---- 配置变化 ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('mind.indentColors') || event.affectsConfiguration('mind.enableIndentLines')) {
        rebuildDecorationTypes(loadConfig());
        const editor = vscode.window.activeTextEditor;
        if (editor?.document.languageId === 'mind') renderIndentLines(editor);
      }
    })
  );

  // ---- 初始渲染 ----
  if (vscode.window.activeTextEditor?.document.languageId === 'mind') {
    renderIndentLines(vscode.window.activeTextEditor);
  }
}

/**
 * 重建所有装饰类型
 */
function rebuildDecorationTypes(config: MindConfig): void {
  // 清理旧装饰
  for (const arr of [branchDecos, lastChildDecos, contDecos]) {
    for (const d of arr) d.dispose();
  }
  branchDecos = [];
  lastChildDecos = [];
  contDecos = [];

  if (!config.enableIndentLines) return;

  const maxLevels = Math.min(config.indentColors.length, 8);
  for (let l = 0; l < maxLevels; l++) {
    const color = config.indentColors[l] || config.indentColors[config.indentColors.length - 1];

    // ├─ 分支（有后续兄弟）
    branchDecos.push(
      vscode.window.createTextEditorDecorationType({
        before: { contentText: '├─ ', color, fontWeight: 'normal', margin: '0 0 0 0' },
        opacity: '0.5',
        rangeBehavior: vscode.DecorationRangeBehavior.OpenOpen,
      })
    );

    // └─ 结尾（最后一个子节点）
    lastChildDecos.push(
      vscode.window.createTextEditorDecorationType({
        before: { contentText: '└─ ', color, fontWeight: 'normal', margin: '0 0 0 0' },
        opacity: '0.5',
        rangeBehavior: vscode.DecorationRangeBehavior.OpenOpen,
      })
    );

    // │ 延续竖线（该层级之后还有内容）
    contDecos.push(
      vscode.window.createTextEditorDecorationType({
        before: { contentText: '│ ', color, fontWeight: 'normal', margin: '0 0 0 0' },
        opacity: '0.4',
        rangeBehavior: vscode.DecorationRangeBehavior.OpenOpen,
      })
    );
  }
}

/**
 * 解析文档中的缩进信息
 * 返回按行索引排列的 { level, text, isEmpty }
 */
function parseIndents(document: vscode.TextDocument): Array<{ level: number; text: string; isEmpty: boolean }> {
  const result: Array<{ level: number; text: string; isEmpty: boolean }> = [];
  for (let i = 0; i < document.lineCount; i++) {
    const text = document.lineAt(i).text;
    if (text.trim() === '') {
      result.push({ level: -1, text: '', isEmpty: true });
    } else {
      const indentMatch = text.match(/^(\s*)/);
      const indentLen = indentMatch ? indentMatch[1].length : 0;
      result.push({ level: Math.floor(indentLen / 2), text, isEmpty: false });
    }
  }
  return result;
}

/**
 * 渲染缩进关系线
 * 基于缩进层级计算分支逻辑
 */
export function renderIndentLines(editor: vscode.TextEditor): void {
  const config = loadConfig();
  if (!config.enableIndentLines || indentDecorationsEmpty()) {
    clearAllDecorations(editor);
    return;
  }

  const lines = parseIndents(editor.document);
  const n = lines.length;

  // 清除所有旧装饰
  clearAllDecorations(editor);

  // 每层级的三种装饰分别收集 ranges
  const branchRanges: vscode.Range[][] = branchDecos.map(() => []);
  const lastRanges: vscode.Range[][] = lastChildDecos.map(() => []);
  const contRanges: vscode.Range[][] = contDecos.map(() => []);

  const maxLevel = branchDecos.length;

  // ---- 第一遍：计算"该层级之后是否还有内容"（延续竖线） ----
  // hasDeeper[maxLevel][lineIdx] = 该层级在 lineIdx 之后还有非空行
  const hasDeeper: boolean[][] = Array.from({ length: maxLevel }, () => new Array(n).fill(false));

  for (let lvl = 0; lvl < maxLevel; lvl++) {
    let found = false;
    for (let i = n - 1; i >= 0; i--) {
      if (lines[i].isEmpty) {
        hasDeeper[lvl][i] = found;
      } else {
        // 当前行是否达到了 lvl？
        hasDeeper[lvl][i] = found || lines[i].level >= lvl;
        if (lines[i].level >= lvl) found = true;
      }
    }
  }

  // ---- 第二遍：分配装饰 ----
  for (let i = 0; i < n; i++) {
    if (lines[i].isEmpty) continue;
    const lvl = lines[i].level;
    if (lvl < 0 || lvl >= maxLevel) continue;

    // 判断当前行是否是其父级下的最后一个子节点
    const isLast = isLastChild(lines, i);

    // 当前的线
    const range = new vscode.Range(i, 0, i, 0);

    if (lvl === 0) {
      contRanges[0].push(range);
    } else if (isLast) {
      lastRanges[lvl].push(range);
    } else {
      branchRanges[lvl].push(range);
    }

    // 为上层绘制延续竖线
    for (let upper = 0; upper < lvl; upper++) {
      if (hasDeeper[upper][i]) {
        contRanges[upper].push(range);
      }
    }
  }

  // ---- 应用装饰 ----
  for (let lvl = 0; lvl < maxLevel; lvl++) {
    if (branchRanges[lvl].length > 0) editor.setDecorations(branchDecos[lvl], branchRanges[lvl]);
    if (lastRanges[lvl].length > 0) editor.setDecorations(lastChildDecos[lvl], lastRanges[lvl]);
    if (contRanges[lvl].length > 0) editor.setDecorations(contDecos[lvl], contRanges[lvl]);
  }
}

/**
 * 判断 lines[i] 是否为其父级下的最后一个子节点
 */
function isLastChild(lines: Array<{ level: number; isEmpty: boolean }>, i: number): boolean {
  const lvl = lines[i].level;
  if (lvl <= 0) return true;

  // 向后找下一个非空行
  for (let j = i + 1; j < lines.length; j++) {
    if (lines[j].isEmpty) continue;
    const nextLvl = lines[j].level;
    if (nextLvl <= lvl) {
      // 找到了同层或上层节点 → 当前节点不是最后一个
      return false;
    }
  }
  // 没找到同层或上层节点 → 当前节点是最后一个
  return true;
}

/**
 * 根据 AI 分析的 nesting 数据更新缩进线
 * 当前实现：忽略 AI nesting 数据，统一用本地缩进计算
 * （AI 的 nesting 可能只覆盖部分行，本地计算更完整）
 */
export function updateDecorationsFromAnalysis(
  editor: vscode.TextEditor,
  _nesting: unknown[]  // 保留签名兼容，但不使用
): void {
  // 用本地方法重新计算（nesting 数据可能不全）
  renderIndentLines(editor);
}

function clearAllDecorations(editor: vscode.TextEditor): void {
  for (const arr of [branchDecos, lastChildDecos, contDecos]) {
    for (const d of arr) editor.setDecorations(d, []);
  }
}

function indentDecorationsEmpty(): boolean {
  return branchDecos.length === 0 && lastChildDecos.length === 0 && contDecos.length === 0;
}

/**
 * ============================================================
 * Mind 插件 — 语义令牌着色
 * ============================================================
 * 注册 VS Code SemanticTokenProvider，根据 AI 分析结果
 * 对 .mind 文件中的词汇进行精细化着色。
 *
 * 数据结构:
 *   resultsMap: Map<URI字符串, AnalysisResult>
 *   - 由 extension.ts 在分析完成后通过 updateSemanticResult() 写入
 *   - buildTokens() 从这里读取，不走 vscode.extensions.getExtension
 *
 * 刷新机制:
 *   - 提供 onDidChangeSemanticTokens 事件发射器
 *   - extension.ts 分析完成后 fire() 通知 VS Code 重新请求
 * ============================================================
 */

import * as vscode from 'vscode';
import { AnalysisResult } from './bridgeClient';

// ============================================================
// 模块级分析结果缓存（替代原先的 getExtension 自引用）
// ============================================================

/** 分析结果缓存: URI字符串 → AnalysisResult */
const resultsMap = new Map<string, AnalysisResult>();

/**
 * 更新语义令牌数据（由 extension.ts 在分析完成后调用）
 */
export function updateSemanticResult(uri: string, result: AnalysisResult): void {
  resultsMap.set(uri, result);
}

/**
 * 清除指定文件的语义令牌数据
 */
export function clearSemanticResult(uri: string): void {
  resultsMap.delete(uri);
}

// ============================================================
// 刷新事件发射器（修复 Bug 2：令牌分析后不刷新）
// ============================================================

const _onDidChangeSemanticTokens = new vscode.EventEmitter<void>();

/**
 * 在分析完成后调用，通知 VS Code 重新请求语义令牌
 */
export function fireSemanticTokensChanged(): void {
  _onDidChangeSemanticTokens.fire();
}

// ============================================================
// Token 类型定义
// ============================================================

/**
 * 自定义语义令牌类型数组
 * 索引与 TYPE_MAP.type 一一对应
 */
const TOKEN_TYPES: string[] = [
  'keyword',   // 0: 控制流关键字 + 自然语言动词
  'function',  // 1: 函数调用/定义
  'variable',  // 2: 变量/实体
  'type',      // 3: 类型关键字
  'number',    // 4: 数字/常量
  'string',    // 5: 字符串/字符
  'operator',  // 6: 运算符
  'comment',   // 7: 注释
];

/**
 * AI 18 种 token 类型 → VS Code 内部类型索引
 */
const TYPE_MAP: Record<string, number> = {
  'keyword':   0,   // keyword
  'c-call':    1,   // function
  'py-def':    1,   // function
  'c-def':     1,   // function
  'decl':      2,   // variable
  'ref':       2,   // variable
  'type':      3,   // type
  'user-type': 3,   // type
  'nl-verb':   0,   // keyword（复用）
  'nl-noun':   2,   // variable（复用）
  'operator':  6,   // operator
  'ptr-op':    6,   // operator
  'number':    4,   // number
  'const':     4,   // number（复用）
  'string':    5,   // string
  'char':      5,   // string
  'comment':   7,   // comment
  // punct 不映射 → 跳过
};

/**
 * 注册语义令牌提供器
 */
export function registerSemanticTokenProvider(context: vscode.ExtensionContext): void {
  const legend = new vscode.SemanticTokensLegend(TOKEN_TYPES, []);

  // ---- 提供器：支持 onDidChangeSemanticTokens 事件 ----
  const provider: vscode.DocumentSemanticTokensProvider & {
    onDidChangeSemanticTokens: vscode.Event<void>;
  } = {
    onDidChangeSemanticTokens: _onDidChangeSemanticTokens.event,

    provideDocumentSemanticTokens(document: vscode.TextDocument): vscode.SemanticTokens {
      return buildTokens(document);
    },
  };

  context.subscriptions.push(
    vscode.languages.registerDocumentSemanticTokensProvider(
      { language: 'mind' },
      provider,
      legend
    )
  );

  // 清理事件发射器
  context.subscriptions.push(_onDidChangeSemanticTokens);
}

/**
 * 构建文档的语义令牌数据
 */
function buildTokens(document: vscode.TextDocument): vscode.SemanticTokens {
  const result = resultsMap.get(document.uri.toString());

  if (!result || !result.tokens || result.tokens.length === 0) {
    return new vscode.SemanticTokens(new Uint32Array(0));
  }

  const builder = new vscode.SemanticTokensBuilder();

  for (const token of result.tokens) {
    const typeIdx = TYPE_MAP[token.type];
    // undefined → punct 等不着色的类型，跳过
    if (typeIdx === undefined) continue;

    const range = new vscode.Range(
      token.line, token.character,
      token.line, token.character + token.length
    );

    builder.push(range, TOKEN_TYPES[typeIdx], []);
  }

  return builder.build();
}

/**
 * ============================================================
 * Mind 插件 — 悬停引用高亮 + 实体信息弹窗
 * ============================================================
 * 当用户悬停在一个实体（变量/函数/概念）上时：
 *   1. 灰色半透明高亮所有逻辑上指向同一对象的词汇
 *   2. 弹窗显示实体信息（名称、类型、描述、引用数量）
 *
 * 效果类似 VS Code 内置的"悬停变量高亮所有引用"。
 *
 * 使用 VS Code API:
 *   - DocumentHighlightProvider → 灰色半透明高亮
 *   - HoverProvider → 弹窗信息
 *
 * 数据来源: AI 分析结果中的 entities 字段
 *   entities[].occurrences 列出了同一实体的所有出现位置
 * ============================================================
 */

import * as vscode from 'vscode';
import { EntityInfo } from './bridgeClient';
import { loadConfig } from './config';

/**
 * 当前文档的分析结果（由 extension.ts 更新）
 * Map: 文件 URI → 实体列表
 */
const analysisResults = new Map<string, EntityInfo[]>();

/**
 * 更新指定文档的实体分析结果
 * 在每次 AI 分析完成后调用
 *
 * @param uri - 文档 URI
 * @param entities - 实体列表
 */
export function updateEntities(uri: string, entities: EntityInfo[]): void {
  analysisResults.set(uri, entities);
}

/**
 * 获取指定位置的实体
 * 边界判断: character 在 [occ.character, occ.character + occ.length) 范围内
 */
function findEntityAtPosition(
  entities: EntityInfo[],
  line: number,
  character: number
): EntityInfo | null {
  for (const entity of entities) {
    for (const occ of entity.occurrences) {
      if (occ.line === line &&
          character >= occ.character &&
          character < occ.character + occ.length) {  // 修复: < 而非 <=
        return entity;
      }
    }
  }
  return null;
}

/**
 * 注册悬停引用高亮功能
 *
 * @param context - 扩展上下文
 */
export function registerHoverFeature(context: vscode.ExtensionContext): void {
  const config = loadConfig();

  // ---- DocumentHighlightProvider: 灰色高亮所有引用 ----
  const highlightProvider = new (class implements vscode.DocumentHighlightProvider {
    provideDocumentHighlights(
      document: vscode.TextDocument,
      position: vscode.Position,
      _token: vscode.CancellationToken
    ): vscode.ProviderResult<vscode.DocumentHighlight[]> {
      // 检查设置开关（修复 Bug 3）
      if (!loadConfig().enableHoverHighlight) return [];

      const entities = analysisResults.get(document.uri.toString());
      if (!entities || entities.length === 0) return [];

      // 查找当前光标所在的实体
      const entity = findEntityAtPosition(entities, position.line, position.character);
      if (!entity) return [];

      // 为该实体的所有 occurrence 创建高亮
      return entity.occurrences.map((occ) => {
        const range = new vscode.Range(
          occ.line, occ.character,
          occ.line, occ.character + occ.length
        );
        return new vscode.DocumentHighlight(range, vscode.DocumentHighlightKind.Read);
      });
    }
  });

  context.subscriptions.push(
    vscode.languages.registerDocumentHighlightProvider(
      { language: 'mind' },
      highlightProvider
    )
  );

  // ---- HoverProvider: 弹窗显示实体信息 ----
  const hoverProvider = new (class implements vscode.HoverProvider {
    provideHover(
      document: vscode.TextDocument,
      position: vscode.Position,
      _token: vscode.CancellationToken
    ): vscode.ProviderResult<vscode.Hover> {
      // 检查设置开关（修复 Bug 3）
      if (!loadConfig().enableHoverHighlight) return null;

      const entities = analysisResults.get(document.uri.toString());
      if (!entities || entities.length === 0) return null;

      // 查找当前悬停的实体
      const entity = findEntityAtPosition(entities, position.line, position.character);
      if (!entity) return null;

      // 构建弹窗内容
      const typeLabel = entityTypeToChinese(entity.type);
      const occurrencesCount = entity.occurrences.length;

      const markdown = new vscode.MarkdownString();
      markdown.isTrusted = true;
      markdown.appendMarkdown(`**${escapeMarkdown(entity.name)}** \\\n`);
      markdown.appendMarkdown(`类型: ${typeLabel} \\\n`);
      markdown.appendMarkdown(`引用: ${occurrencesCount} 处 \\\n`);
      if (entity.description) {
        markdown.appendMarkdown(`---\n${escapeMarkdown(entity.description)}\n`);
      }
      // 添加灰色提示
      markdown.appendMarkdown(`\n---\n_悬停时灰色高亮显示所有引用_\n`);

      return new vscode.Hover(markdown);
    }
  });

  context.subscriptions.push(
    vscode.languages.registerHoverProvider(
      { language: 'mind' },
      hoverProvider
    )
  );
}

/**
 * 将实体类型映射为中文描述
 */
function entityTypeToChinese(type: string): string {
  const map: Record<string, string> = {
    'variable': '变量',
    'function': '函数',
    'concept': '概念',
    'class': '类',
    'module': '模块',
    'constant': '常量',
  };
  return map[type] || type;
}

/**
 * 转义 Markdown 特殊字符
 */
function escapeMarkdown(text: string): string {
  return text.replace(/([\\`*_{}[\]()#+\-.!])/g, '\\$1');
}

/**
 * ============================================================
 * Mind 插件 — 诊断管理
 * ============================================================
 * 管理两种诊断标记:
 *   1. 红色波浪下划线 → 确定逻辑错误（未定义实体/矛盾操作等）
 *   2. 绿色波浪下划线 → AI 不理解的标记（歧义/未知词汇等）
 *
 * 两种标记在 VS Code 问题面板（Problems Panel）中显示。
 * 悬停在波浪线上时弹窗显示错误/警告消息。
 *
 * VS Code API:
 *   - DiagnosticCollection: 管理诊断条目集合
 *   - DiagnosticSeverity.Error: 红色波浪线
 *   - DiagnosticSeverity.Warning: 绿色波浪线
 * ============================================================
 */

import * as vscode from 'vscode';
import { DiagnosticInfo } from './bridgeClient';
import { loadConfig } from './config';

/** 全局诊断集合 */
let diagnosticCollection: vscode.DiagnosticCollection;

/**
 * 初始化诊断管理
 * 创建诊断集合并注册到 VS Code
 *
 * @param context - 扩展上下文
 */
export function registerDiagnosticManager(context: vscode.ExtensionContext): void {
  // 创建诊断集合（名为 "Mind" 在问题面板中显示）
  diagnosticCollection = vscode.languages.createDiagnosticCollection('mind');
  context.subscriptions.push(diagnosticCollection);

  // ---- 监听配置变化（实时更新下划线颜色） ----
  context.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration('mind.enableDiagnostics') ||
          event.affectsConfiguration('mind.errorColor') ||
          event.affectsConfiguration('mind.warningColor')) {
        // 清除所有诊断，等待下一次分析重建
        diagnosticCollection.clear();
      }
    })
  );
}

/**
 * 更新指定文件的诊断信息
 *
 * @param uri - 文件 URI
 * @param diagnostics - AI 分析的诊断列表
 */
export function updateDiagnostics(uri: vscode.Uri, diagnostics: DiagnosticInfo[]): void {
  const config = loadConfig();

  // 如果诊断被禁用，直接清空并返回
  if (!config.enableDiagnostics || !diagnostics || diagnostics.length === 0) {
    diagnosticCollection.set(uri, []);
    return;
  }

  // ---- 将 AI 诊断转换为 VS Code 诊断 ----
  const vsCodeDiagnostics: vscode.Diagnostic[] = diagnostics.map((d) => {
    // 计算诊断范围
    const range = new vscode.Range(
      d.line, d.character,
      d.line, d.character + (d.length || 1)
    );

    // 映射严重程度
    const severity = d.severity === 'error'
      ? vscode.DiagnosticSeverity.Error    // 红色波浪线
      : vscode.DiagnosticSeverity.Warning;  // 绿色波浪线

    // 创建诊断对象
    const diagnostic = new vscode.Diagnostic(range, d.message, severity);

    // 设置诊断来源
    diagnostic.source = 'Mind (语义分析)';

    // 为错误类型添加更详细的描述
    if (d.severity === 'error') {
      diagnostic.tags = [vscode.DiagnosticTag.Unnecessary];
      diagnostic.code = {
        value: 'mind-error',
        target: vscode.Uri.parse('https://github.com/mind-lang/mind-extension#error-types'),
      };
    } else {
      // 警告（绿色波浪线）添加提示
      diagnostic.code = {
        value: 'mind-uncertain',
        target: vscode.Uri.parse('https://github.com/mind-lang/mind-extension#warning-types'),
      };
    }

    return diagnostic;
  });

  // 更新诊断集合
  diagnosticCollection.set(uri, vsCodeDiagnostics);
}

/**
 * 清除指定文件的所有诊断
 *
 * @param uri - 文件 URI，不传则清除全部
 */
export function clearDiagnostics(uri?: vscode.Uri): void {
  if (uri) {
    diagnosticCollection.set(uri, []);
  } else {
    diagnosticCollection.clear();
  }
}

/**
 * 获取指定文件的诊断数量统计
 *
 * @param uri - 文件 URI
 * @returns { errors: number, warnings: number }
 */
export function getDiagnosticStats(uri: vscode.Uri): { errors: number; warnings: number } {
  const diagnostics = diagnosticCollection.get(uri);
  if (!diagnostics) return { errors: 0, warnings: 0 };

  let errors = 0;
  let warnings = 0;

  for (const d of diagnostics) {
    if (d.severity === vscode.DiagnosticSeverity.Error) {
      errors++;
    } else {
      warnings++;
    }
  }

  return { errors, warnings };
}

/**
 * ============================================================
 * Mind 插件 — 超链接导航
 * ============================================================
 * 在三文件之间创建可点击的超链接：
 *
 *   .mind ←──────────────── .py
 *    # @d 实现XX             def XX():
 *     ↑ 可点击                 ↑ 可点击
 *     └──────────────────── .c
 *                            void XX() {
 *
 * DocumentLinkProvider 实现:
 *   - .mind 文件: # @d 注释 → 可点击跳转到对应的 .py/.c 函数
 *   - .py 文件: 函数签名 → 可点击跳回对应的 .mind 注释
 *   - .c 文件: 函数签名 → 可点击跳回对应的 .mind 注释
 *
 * 数据来源: GenerationResult 中的 links 数组
 * ============================================================
 */

import * as vscode from 'vscode';
import { GenerationResult, FileCode } from './bridgeClient';
import { getTripletUris } from './fileTriplet';

/**
 * 当前文档的代码生成链接数据
 * Map: .mind URI → GenerationResult
 */
const generationData = new Map<string, GenerationResult>();

/**
 * 更新生成结果（由 extension.ts 在生成完成后调用）
 */
export function updateGenerationData(uri: string, result: GenerationResult): void {
  generationData.set(uri, result);
}

/**
 * 注册所有超链接提供器
 *
 * @param context - 扩展上下文
 */
export function registerDocLinks(context: vscode.ExtensionContext): void {
  // ---- 1. .mind → .py / .c 链接 ----
  // 在 .mind 文件中，# @d 注释文本可点击，指向生成的 .py/.c 函数
  context.subscriptions.push(
    vscode.languages.registerDocumentLinkProvider(
      { language: 'mind', scheme: 'file' },
      new MindLinkProvider()
    )
  );

  // ---- 2. .py → .mind 反向链接 ----
  context.subscriptions.push(
    vscode.languages.registerDocumentLinkProvider(
      { language: 'python', scheme: 'file' },
      new GeneratedFileLinkProvider('py')
    )
  );

  // ---- 3. .c → .mind 反向链接 ----
  context.subscriptions.push(
    vscode.languages.registerDocumentLinkProvider(
      { language: 'c', scheme: 'file' },
      new GeneratedFileLinkProvider('c')
    )
  );
}

/**
 * .mind 文件中的 DocumentLinkProvider
 * 将 # @d 注释转换为可点击链接，跳转到 .py/.c 中的实现
 */
class MindLinkProvider implements vscode.DocumentLinkProvider {
  provideDocumentLinks(
    document: vscode.TextDocument,
    _token: vscode.CancellationToken
  ): vscode.ProviderResult<vscode.DocumentLink[]> {
    const result = generationData.get(document.uri.toString());
    if (!result) return [];

    const links: vscode.DocumentLink[] = [];
    const uris = getTripletUris(document.uri.fsPath);

    // 处理 Python 链接
    if (result.py?.links) {
      for (const link of result.py.links) {
        const range = new vscode.Range(link.mindLine, 0, link.mindLine, 255);
        // 目标: .py 文件的 link.fileLine 行
        const target = uris.pyUri.with({
          fragment: `${link.fileLine + 1}`,  // VS Code 的行号从 1 起始
        });
        links.push(new vscode.DocumentLink(range, target));
      }
    }

    // 处理 C 链接
    if (result.c?.links) {
      for (const link of result.c.links) {
        const range = new vscode.Range(link.mindLine, 0, link.mindLine, 255);
        const target = uris.cUri.with({
          fragment: `${link.fileLine + 1}`,
        });
        links.push(new vscode.DocumentLink(range, target));
      }
    }

    return links;
  }
}

/**
 * 生成文件（.py / .c）中的 DocumentLinkProvider
 * 将函数签名处的注释转换为可点击链接，跳回 .mind 中的 # @d
 */
class GeneratedFileLinkProvider implements vscode.DocumentLinkProvider {
  constructor(private lang: 'py' | 'c') {}

  provideDocumentLinks(
    document: vscode.TextDocument,
    _token: vscode.CancellationToken
  ): vscode.ProviderResult<vscode.DocumentLink[]> {
    // 查找生成数据中哪个条目的 py/c 代码属于此文件
    for (const [mindUri, result] of generationData) {
      const fileCode = this.lang === 'py' ? result.py : result.c;
      if (!fileCode || !fileCode.links) continue;

      // 通过检查文件名来匹配（简单但有效）
      const mindPath = vscode.Uri.parse(mindUri).fsPath;
      const triplet = getTripletUris(mindPath);
      const targetUri = this.lang === 'py' ? triplet.pyUri : triplet.cUri;

      if (document.uri.fsPath.toLowerCase() !== targetUri.fsPath.toLowerCase()) {
        continue; // 不匹配
      }

      // 为每个链接的反向创建链接
      const links: vscode.DocumentLink[] = [];
      const mindTarget = vscode.Uri.parse(mindUri).with({
        fragment: `${fileCode.links[0].mindLine + 1}`,
      });

      for (const link of fileCode.links) {
        // 在函数起始行添加"回到 .mind"链接
        // 我们把它放在函数签名前面作为注释行
        const range = new vscode.Range(link.fileLine, 0, link.fileLine, 100);
        links.push(new vscode.DocumentLink(range, mindTarget));
      }

      return links;
    }

    return [];
  }
}

/**
 * ============================================================
 * Mind 插件 — 三文件关系管理
 * ============================================================
 * 管理 .mind ↔ .py ↔ .c 三文件体系：
 *
 *   同一文件夹/
 *   ├── project.mind    ← 用户写的需求规格
 *   ├── project.py      ← 插件自动生成的 Python 实现
 *   └── project.c       ← 插件自动生成的 C 实现
 *
 * 功能:
 *   1. 打开 .mind 时自动发现/创建同名的 .py 和 .c
 *   2. 提供文件路径映射（三文件互查）
 *   3. 写入生成代码到 .py / .c（增量更新，保留已有内容）
 * ============================================================
 */

import * as vscode from 'vscode';
import { FileCode } from './bridgeClient';

/** 三文件路径映射 */
export interface FileTriplet {
  /** .mind 文件路径 */
  mind: string;
  /** .py 文件路径（自动生成） */
  py: string;
  /** .c 文件路径（自动生成） */
  c: string;
  /** 文件基础名（不含扩展名） */
  basename: string;
  /** 所在目录 */
  dir: string;
}

/**
 * 根据 .mind 文件路径获取三文件映射
 *
 * @param mindPath - .mind 文件的绝对路径（fsPath）
 * @returns 三文件映射
 */
export function getTriplet(mindPath: string): FileTriplet {
  const dir = mindPath.substring(0, mindPath.lastIndexOf('\\'));
  const basename = mindPath.substring(
    mindPath.lastIndexOf('\\') + 1,
    mindPath.lastIndexOf('.')
  );

  return {
    mind: mindPath,
    py: `${dir}\\${basename}.py`,
    c: `${dir}\\${basename}.c`,
    basename,
    dir,
  };
}

/**
 * 获取 .mind 文件对应的三文件 URI 列表
 * 供 DocumentLinkProvider 等使用
 */
export function getTripletUris(mindPath: string): { pyUri: vscode.Uri; cUri: vscode.Uri } {
  const t = getTriplet(mindPath);
  return {
    pyUri: vscode.Uri.file(t.py),
    cUri: vscode.Uri.file(t.c),
  };
}

/**
 * 确保三文件体系完整
 * 如果 .py 或 .c 不存在，创建空文件
 *
 * @param mindPath - .mind 文件路径
 */
export async function ensureTripletFiles(mindPath: string): Promise<void> {
  const t = getTriplet(mindPath);

  // 创建目录（确保 exist）
  const dirUri = vscode.Uri.file(t.dir);

  for (const filePath of [t.py, t.c]) {
    try {
      await vscode.workspace.fs.stat(vscode.Uri.file(filePath));
      // 文件已存在，跳过
    } catch {
      // 文件不存在，创建空文件
      const header = getFileHeader(filePath, t.basename);
      await vscode.workspace.fs.writeFile(
        vscode.Uri.file(filePath),
        new TextEncoder().encode(header)
      );
      console.log(`[文件体系] 创建: ${filePath}`);
    }
  }
}

/**
 * 写入生成的代码到 .py 或 .c 文件
 * 保留文件头部注释，追加或替换函数实现
 *
 * @param filePath - 目标文件路径
 * @param fileCode - 生成代码内容
 */
export async function writeGeneratedCode(
  filePath: string,
  fileCode: FileCode
): Promise<void> {
  const uri = vscode.Uri.file(filePath);

  if (!fileCode.code || fileCode.code.trim().length === 0) return;

  try {
    await vscode.workspace.fs.writeFile(uri, new TextEncoder().encode(fileCode.code));
    console.log(`[文件体系] 写入: ${filePath} (${fileCode.code.length} 字符)`);
  } catch (error) {
    console.error(`[文件体系] 写入失败: ${filePath}`, error);
  }
}

/**
 * 生成空文件的起始内容（含注释说明）
 */
function getFileHeader(filePath: string, basename: string): string {
  if (filePath.endsWith('.py')) {
    return (
      `# ============================================================\n` +
      `# ${basename}.py — 自动生成代码\n` +
      `# 由 Mind 插件根据 ${basename}.mind 中的 # @d 注释自动生成\n` +
      `# 请勿手动修改此文件，修改请在 .mind 文件中修改后重新生成\n` +
      `# ============================================================\n\n\n`
    );
  } else {
    return (
      `// ============================================================\n` +
      `// ${basename}.c — 自动生成代码\n` +
      `// 由 Mind 插件根据 ${basename}.mind 中的 # @d 注释自动生成\n` +
      `// 请勿手动修改此文件，修改请在 .mind 文件中修改后重新生成\n` +
      `// ============================================================\n\n\n`
    );
  }
}

/**
 * ============================================================
 * Mind 插件 — 独立对话管理
 * ============================================================
 * 管理插件与 AI 后端之间的"对话"会话。
 *
 * 核心功能:
 *   1. 每个 .mind 文件自动创建专属"对话上下文"
 *   2. 切换文件时自动切换对话
 *   3. 同一文件的多次分析共享上下文（历史记录）
 *   4. 文件关闭时自动结束对话
 *
 * 注意: 当前实现中，由于 mind-bridge 是无状态 HTTP 服务，
 * 每次请求都发送完整文件内容。真正的"对话"是通过 DeepSeek
 * 的 API 缓存实现的——相同的文件内容命中缓存，无需重新推理。
 *
 * 如果需要真正的多轮对话（追踪文件修改历史），可以扩展
 * mind-bridge 添加 session 管理功能。
 * ============================================================
 */

import * as vscode from 'vscode';

/** 对话会话接口 */
interface Session {
  /** 会话唯一标识 */
  id: string;
  /** 文件路径（作为标识） */
  filePath: string;
  /** 创建时间 */
  createdAt: Date;
  /** 最后活跃时间 */
  lastActive: Date;
  /** 分析次数 */
  analysisCount: number;
}

/** 会话存储 Map: 文件路径 → Session */
const sessions = new Map<string, Session>();

/** 当前活跃会话的文件路径 */
let activeSessionPath: string | null = null;

/**
 * 获取或创建文件对应的会话
 *
 * @param filePath - 文件的绝对路径
 * @returns 会话对象
 */
export function getOrCreateSession(filePath: string): Session {
  let session = sessions.get(filePath);

  if (!session) {
    // 创建新会话
    session = {
      id: `mind-session-${filePath.replace(/[^a-zA-Z0-9]/g, '-')}`,
      filePath,
      createdAt: new Date(),
      lastActive: new Date(),
      analysisCount: 0,
    };
    sessions.set(filePath, session);
    console.log(`[会话] 创建新会话: ${filePath}`);
  }

  return session;
}

/**
 * 切换到指定文件的会话
 *
 * @param filePath - 文件路径
 */
export function activateSession(filePath: string): void {
  const session = getOrCreateSession(filePath);
  session.lastActive = new Date();
  activeSessionPath = filePath;
}

/**
 * 记录一次分析请求
 *
 * @param filePath - 文件路径
 */
export function recordAnalysis(filePath: string): void {
  const session = getOrCreateSession(filePath);
  session.analysisCount++;
  session.lastActive = new Date();
}

/**
 * 关闭文件时结束会话
 *
 * @param filePath - 文件路径
 */
export function closeSession(filePath: string): void {
  const session = sessions.get(filePath);
  if (session) {
    console.log(`[会话] 结束会话: ${filePath} (分析次数: ${session.analysisCount})`);
    sessions.delete(filePath);

    if (activeSessionPath === filePath) {
      activeSessionPath = null;
    }
  }
}

/**
 * 获取当前活跃会话
 */
export function getActiveSession(): Session | null {
  if (activeSessionPath) {
    return sessions.get(activeSessionPath) || null;
  }
  return null;
}

/**
 * 获取所有活跃会话统计
 */
export function getSessionStats(): { total: number; active: Session | null } {
  return {
    total: sessions.size,
    active: getActiveSession(),
  };
}

/**
 * 获取会话历史摘要
 * 用于在 UI 中显示
 */
export function getSessionSummary(filePath: string): string {
  const session = sessions.get(filePath);
  if (!session) return '无活跃会话';

  const minutesSinceActive = Math.floor(
    (Date.now() - session.lastActive.getTime()) / 60000
  );

  return [
    `对话标识: ${session.id.slice(0, 40)}...`,
    `分析次数: ${session.analysisCount}`,
    `上次活跃: ${minutesSinceActive} 分钟前`,
  ].join('\n');
}

/**
 * 注册对话管理的事件监听
 *
 * @param context - 扩展上下文
 */
export function registerSessionManager(context: vscode.ExtensionContext): void {
  // ---- 监听编辑器切换 ----
  context.subscriptions.push(
    vscode.window.onDidChangeActiveTextEditor((editor) => {
      if (editor && editor.document.languageId === 'mind') {
        activateSession(editor.document.uri.fsPath);
      }
    })
  );

  // ---- 监听文档关闭 ----
  context.subscriptions.push(
    vscode.workspace.onDidCloseTextDocument((document) => {
      if (document.languageId === 'mind') {
        closeSession(document.uri.fsPath);
      }
    })
  );

  // ---- 初始会话激活 ----
  const editor = vscode.window.activeTextEditor;
  if (editor && editor.document.languageId === 'mind') {
    activateSession(editor.document.uri.fsPath);
  }
}

