from typing import Optional

# 定义链表节点类
class ListNode:
    """链表节点类，包含值和下一个节点指针"""
    def __init__(self, val: int = 0, next: Optional['ListNode'] = None):
        self.val = val
        self.next = next

def reverse_list(head: Optional[ListNode]) -> Optional[ListNode]:
    """
    反转单向链表
    参数:
        head: 原链表的头节点
    返回:
        反转后的链表头节点
    逻辑:
        使用三个指针：prev, curr, next 迭代反转每个节点的next指向
    """
    # 如果链表为空或只有一个节点，直接返回head
    if head is None or head.next is None:
        return head

    prev = None  # 前一个节点，初始为None
    curr = head  # 当前节点，从头开始

    # 遍历链表，直到curr为None
