{"command": "node -e "
const fs=require('fs');
// Check start.bat for path issues
const start=fs.readFileSync('Structured-Pseudocode/package/start.bat','utf8');
const lines=start.split('\r\n');
let issues=[];
for(let i=0;i<lines.length;i++){
  const l=lines[i];
  // Check cd paths
  if(l.includes('cd /d') && l.includes('BRIDGE') || l.includes('EXT')){
    if(!l.includes('!BRIDGE!') && !l.includes('!EXT!') && !l.includes('%BRIDGE%') && !l.includes('%EXT%')){
      issues.push('Line '+(i+1)+': possible path issue - '+l.trim());
    }
  }
  // Check for unbalanced parentheses
  const opens=(l.match(/\(/g)||[]).length;
  const closes=(l.match(/\)/g)||[]).length;
  // Actually let's just check the whole file balance
}
// Count parens
let open=0, close=0;
for(const c of start){
  if(c==='(') open++;
  if(c===')') close++;
}
console.log('start.bat: parens open='+open+' close='+close+' balanced='+(open===close));
console.log('Has setlocal:', start.includes('setlocal'));
console.log('Has endlocal:', start.includes('endlocal'));
console.log('Uses BRIDGE_DIR:', start.includes('BRIDGE_DIR'));
console.log('Uses BRIDGE:', start.includes('BRIDGE'));
console.log('Uses EXT:', start.includes('EXT'));
""}

