const files=[
  'AI   文件夹/Structured-Pseudocode/package/start.bat',
  'AI   文件夹/Structured-Pseudocode/package/update.bat',
  'AI   文件夹/Mind-语言系统-安装包/start.bat',
  'AI   文件夹/Mind-语言系统-安装包/update.bat',
  'AI   文件夹/启动Mind系统.bat'
];
const oldText='[分析代码变量]';
const newText='[分析代码变量]  [AI修正颜色]  [AI创建悬停]  [AI检测注释]';
const detail = `echo    [分析代码变量]    分析变量/颜色/诊断
echo    [AI修正颜色]      AI 重新分析并修正颜色
echo    [AI创建悬停]      AI 构建实体关系缓存
echo    [AI检测注释]      检测 # @d 生成 Python`;

files.forEach(f=>{
  let c=fs.readFileSync(f,'utf8');
  if(c.includes(oldText)){
    // Replace old 2-button description with 4-button
    c=c.replace(/echo.*分析代码变量.*\r?\n.*AI检测[^\\n]*/g, detail);
    // Also fix the single-line version
    c=c.replace(/\[分析代码变量\][^\]]*\]/g, newText);
    fs.writeFileSync(f,c,'utf8');
    console.log(f.split('/').pop()+': updated');
  } else {
    console.log(f.split('/').pop()+': skip (no old text)');
  }
});
