{"content": "/**
 * Reasonix 客户端 — 替代直接调用 DeepSeek API
 * 通过 reasonix run 命令调用 AI，自动使用 Reasonix 的配置
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

/**
 * 通过 reasonix run 调用 AI
 * @param {string} systemPrompt - 系统提示词
 * @param {string} userContent - 用户输入
 * @returns {Promise<{content: string, tokenUsage: object}>}
 */
export async function callReasonix(systemPrompt, userContent) {
  // 创建临时系统提示词文件（避免命令行转义问题）
  const tmpFile = path.join(os.tmpdir(), `mind-prompt-${Date.now()}.txt`);
  const transcriptFile = path.join(os.tmpdir(), `mind-transcript-${Date.now()}.jsonl`);

  const fullPrompt = `${systemPrompt}\n\n${userContent}`;
  fs.writeFileSync(tmpFile, fullPrompt, 'utf-8');

  try {
    const cmd = `reasonix run -s "${systemPrompt}" --transcript "${transcriptFile}" "${userContent.substring(0, 200)}"`;
    const stdout = execSync(cmd, {
      timeout: 120000,
      encoding: 'utf-8',
      maxBuffer: 10 * 1024 * 1024,
    });

    // 从转录文件中提取 AI 回复
    let response = '';
    if (fs.existsSync(transcriptFile)) {
      const lines = fs.readFileSync(transcriptFile, 'utf-8').trim().split('\n');
      for (const line of lines) {
        try {
          const entry = JSON.parse(line);
          if (entry.role === 'assistant' && entry.content) {
            response += entry.content;
          }
        } catch {}
      }
    }

    // 如果转录文件没有内容，直接从 stdout 提取
    if (!response) {
      response = stdout;
    }

    // 清理临时文件
    try { fs.unlinkSync(tmpFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}

    if (!response || !response.trim()) {
      throw new Error('AI 返回了空响应');
    }

    // 简单的 token 估算（reasonix 不返回用量，用字符数估算）
    const promptTokens = Math.ceil(fullPrompt.length / 3);
    const completionTokens = Math.ceil(response.length / 3);
    const tokenUsage = {
      prompt: promptTokens,
      completion: completionTokens,
      total: promptTokens + completionTokens,
      cached: 0,
    };

    return { content: response, tokenUsage };

  } catch (error) {
    try { fs.unlinkSync(tmpFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}
    throw error;
  }
}
