{"content": "/**
 * Reasonix AI 客户端
 * 通过 reasonix run 调用 AI，替代直接调用 DeepSeek API
 * 自动使用 Reasonix 的配置、缓存、代理
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

/**
 * 通过 reasonix run 调用 AI
 * @param {string} systemPrompt - 系统提示词
 * @param {string} userContent - 用户输入
 * @returns {Promise<{content: string, tokenUsage: object}>}
 */
export async function callDeepSeek(systemPrompt, userContent) {
  // 创建临时文件保存完整输入（避免命令行长度限制和转义问题）
  const inputFile = path.join(os.tmpdir(), `mind-input-${Date.now()}.txt`);
  const transcriptFile = path.join(os.tmpdir(), `mind-transcript-${Date.now()}.jsonl`);

  const fullInput = `${systemPrompt}\n\n---\n\n${userContent}`;
  fs.writeFileSync(inputFile, fullInput, 'utf-8');

  try {
    // 用 reasonix run 执行分析
    // -s 系统提示词（简短版本）
    // --transcript 保存转录用于提取结果
    // 管道输入完整内容
    const cmd = `reasonix run -s "${systemPrompt.substring(0, 100)}" --preset flash --transcript "${transcriptFile}" < "${inputFile}"`;

    const stdout = execSync(cmd, {
      timeout: 180000, // 3 分钟超时
      encoding: 'utf-8',
      maxBuffer: 20 * 1024 * 1024,
      shell: true,
    });

    // 从转录文件中提取 AI 回复
    let response = '';
    if (fs.existsSync(transcriptFile)) {
      const raw = fs.readFileSync(transcriptFile, 'utf-8').trim();
      if (raw) {
        const lines = raw.split('\n');
        for (const line of lines) {
          try {
            const entry = JSON.parse(line);
            if (entry.role === 'assistant' && entry.content) {
              response += entry.content;
            }
          } catch {}
        }
      }
    }

    // 如果转录没有内容，直接从 stdout 提取
    if (!response) {
      response = stdout.trim();
    }

    // 清理临时文件
    try { fs.unlinkSync(inputFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}

    if (!response) {
      throw new Error('AI 返回了空响应');
    }

    // Reasonix 不直接返回 token 用量，用字符数估算
    const promptTokens = Math.ceil(fullInput.length / 3);
    const completionTokens = Math.ceil(response.length / 3);
    const tokenUsage = {
      prompt: promptTokens,
      completion: completionTokens,
      total: promptTokens + completionTokens,
      cached: 0,
    };

    return { content: response, tokenUsage };

  } catch (error) {
    // 清理临时文件
    try { fs.unlinkSync(inputFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}

    // 错误分类
    const msg = error.message || '';
    if (msg.includes('401') || msg.includes('Unauthorized')) {
      const err = new Error('Reasonix 认证失败');
      err.status = 401;
      throw err;
    }
    if (msg.includes('timeout') || msg.includes('ETIMEDOUT')) {
      const err = new Error('Reasonix 请求超时');
      err.code = 'ETIMEDOUT';
      throw err;
    }
    throw error;
  }
}
