{"content": "/**
 * AI 客户端 — 通过 reasonix run 调用
 * 所有 AI 服务都走 Reasonix 管线
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

export async function callDeepSeek(systemPrompt, userContent) {
  const ts = Date.now();
  const tmpDir = os.tmpdir();

  // 写入 .mind 内容到临时文件
  const mindFile = path.join(tmpDir, `mind-content-${ts}.mind`);
  fs.writeFileSync(mindFile, userContent, 'utf-8');

  // 写入完整的系统提示词到文件
  const promptFile = path.join(tmpDir, `mind-prompt-${ts}.txt`);
  fs.writeFileSync(promptFile, systemPrompt, 'utf-8');

  // 转录文件（reasonix 自动写入）
  const transcriptFile = path.join(tmpDir, `mind-result-${ts}.jsonl`);

  try {
    // reasonix run 命令
    // -s: 简短提示词
    // --mcp filesystem: 让 reasonix 能读取文件
    // --preset flash: 使用 flash 模型
    // --transcript: 保存结果
    const task = `分析 ${mindFile} 文件内容，按照提示词要求返回 JSON`;
    const shortPrompt = `分析 .mind 文件语义。返回 JSON。详细提示词在 ${promptFile}`;

    const mcpSpec = `filesystem=${path.dirname(mindFile)}`;
    const cmd = `reasonix run -s "${shortPrompt}" --preset flash --transcript "${transcriptFile}" --mcp "${mcpSpec}" "${task}"`;

    execSync(cmd, {
      timeout: 180000,
      encoding: 'utf-8',
      maxBuffer: 50 * 1024 * 1024,
      shell: true,
      stdio: 'pipe',
    });

    // 从转录提取 AI 回复
    let response = '';
    if (fs.existsSync(transcriptFile)) {
      const raw = fs.readFileSync(transcriptFile, 'utf-8').trim();
      if (raw) {
        for (const line of raw.split('\n')) {
          try {
            const entry = JSON.parse(line);
            if (entry.role === 'assistant' && entry.content) {
              response += entry.content;
            }
          } catch {}
        }
      }
    }

    // 如果转录为空，可能是流式输出还没写入，重试一次
    if (!response && fs.existsSync(transcriptFile)) {
      await new Promise(r => setTimeout(r, 1000));
      const raw = fs.readFileSync(transcriptFile, 'utf-8').trim();
      for (const line of raw.split('\n')) {
        try { const e = JSON.parse(line); if (e.role === 'assistant' && e.content) response += e.content; } catch {}
      }
    }

    // 清理
    try { fs.unlinkSync(mindFile); } catch {}
    try { fs.unlinkSync(promptFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}

    if (!response.trim()) throw new Error('AI 返回了空响应');

    return {
      content: response,
      tokenUsage: {
        prompt: Math.ceil((systemPrompt.length + userContent.length) / 3),
        completion: Math.ceil(response.length / 3),
        total: Math.ceil((systemPrompt.length + userContent.length + response.length) / 3),
        cached: 0,
      },
    };

  } catch (error) {
    try { fs.unlinkSync(mindFile); } catch {}
    try { fs.unlinkSync(promptFile); } catch {}
    try { fs.unlinkSync(transcriptFile); } catch {}
    throw error;
  }
}
