{"command": "node -e "
const fs=require('fs');
const bats=[
  'AI   文件夹/Structured-Pseudocode/package/start.bat',
  'AI   文件夹/Structured-Pseudocode/package/update.bat',
  'AI   文件夹/Mind-语言系统-安装包/start.bat',
  'AI   文件夹/Mind-语言系统-安装包/update.bat',
  'AI   文件夹/启动Mind系统.bat'
];

// For each bat file, replace the 4-button descriptions with 5-button
bats.forEach(p=>{
  let c=fs.readFileSync(p,'utf8');
  const n=p.split('/').pop();

  // Replace fix colors line to add clearAI
  c=c.replace(/AI修正颜色[^\\n]*/g, 'AI修正颜色');
  c=c.replace(/AI检测注释[^\\n]*/g, 'AI检测注释');

  // Add clearAI if not present
  if(!c.includes('清除AI')){
    // For git/install start.bat
    c=c.replace(
      /echo.*AI检测注释.*生成 Python/,
      'echo    [AI检测注释]      检测 # @d 生成 Python\r\necho    [清除AI标记]      删除 AI 颜色和装饰，恢复 TextMate'
    );
    // For update.bat
    c=c.replace(
      /echo.*AI检测注释并生成/,
      'echo    [AI检测注释]      检测 # @d 并生成 Python\r\necho    [清除AI标记]      删除 AI 颜色和装饰'
    );
  }

  fs.writeFileSync(p,c,'utf8');
  const has5btn=c.includes('清除AI')||c.includes('5 button');
  console.log(n+': '+(c.includes('清除AI')?'✅ updated':'⬜ unchanged'));
});
" 2>&1"}

